INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES
(1124, 'plPL', 'Pustkowie', 'Na zachód od Krateru Un\'Goro, za północno-zachodnią granią, leży surowe pustkowie – Silithus. Niewielu wie, że toczyła się tam niegdyś pradawna wojna między nocnymi elfami a złowrogą, obcą potęgą. Zło zostało zapieczętowane, lecz podejrzewamy, że jakieś siły próbują przebudzić tę... niewypowiedzianą grozę.$B$BOdszukaj Layo Gwiezdne Uderzenie, jednego z naszych agentów w Silithusie; znajdziesz go przy Spoczynku Męstwa, miejscu wiecznego spoczynku poległych na pustkowiu. Daj mu ten list, a obdarzy cię zaufaniem.', 'Porozmawiaj z Layo Gwiezdnym Uderzeniem przy cmentarzu Spoczynek Męstwa w Silithusie i pokaż mu list Rabine\'a.', '', '', '', '', '', '', 0),
(1125, 'plPL', 'Duchy Południowego Wiatru', 'Na południowy zachód od nas leży miejsce tragedii – ruiny Osady Południowego Wiatru. To tam powinniśmy zacząć pracę, $N.$B$BZ tego, czego się dowiedzieliśmy, osada była niegdyś bazą operacyjną nocnych elfów w Silithusie. Dawno temu zalały ją silithidzkie roje, które plenią się na pustkowiu. Mogę sobie tylko wyobrazić grozę jej pierwszego upadku...$B$BUmęczone duchy poległych druidów i strażniczek błąkają się bez celu po ruinach. Zbadaj to miejsce i w razie potrzeby uwolnij dusze tych nieszczęsnych istot.', 'Uwolnij duchy 8 umęczonych druidów i 8 umęczonych strażniczek w Osadzie Południowego Wiatru, a następnie wróć do Layo Gwiezdnego Uderzenia przy cmentarzu Spoczynek Męstwa w Silithusie.', '', 'Wróć do Layo Gwiezdnego Uderzenia w Silithusie.', '', '', '', '', 0),
(1126, 'plPL', 'Rój w wieży', 'Trzeba się zająć rojem w Osadzie Południowego Wiatru i chyba wiem, jak się do nich dobrać. Z mojego doświadczenia wynika, że silithidzkie roje są bardzo wyczulone na otoczenie; to tłumaczy, dlaczego atakują, gdy słyszą zawodzenie duchów.$B$BSilithidy są najsilniejsze w wieży – tej, wokół której krąży chmara os. Wespnij się na wieżę i pobudź rój do działania. Wróć i opowiedz mi, czego się $gdowiedziałeś:dowiedziałaś;, ale uważaj! Jeśli znajdziesz coś, co mogłoby pomóc, przynieś mi to.', 'Wespnij się na wieżę w Osadzie Południowego Wiatru i znajdź sposób, by pobudzić silithidzki rój do działania. Wszystko, co niezwykłego przy tym znajdziesz, zanieś Layo Gwiezdnemu Uderzeniu przy cmentarzu Spoczynek Męstwa w Silithusie.', '', 'Wróć do Layo Gwiezdnego Uderzenia w Silithusie.', '', '', '', '', 0),
(1155, 'plPL', '<NYI> <TXT> Zadanie poboczne z kryształem robali', '', '', '', '', '', '', '', '', 0),
(1156, 'plPL', '<NYI> <TXT> Rozmowa z alchemikiem Pestlezuggiem', '', '', '', '', '', '', '', '', 0),
(1161, 'plPL', '<NYI> <TXT> Rozmowa z Cieniem Bursztynowego Księżyca', '', '', '', '', '', '', '', '', 0),
(1162, 'plPL', '<NYI> <TXT> Rozmowa z Hamuulem Runicznym Totemem', '', '', '', '', '', '', '', '', 0),
(1163, 'plPL', '<NYI> <TXT> Rozmowa z Tyrande Szept Wiatru', '', '', '', '', '', '', '', '', 0),
(6844, 'plPL', 'Umber, archiwista', 'Wciąż jest tu mnóstwo do zrobienia, ale uważam, że najważniejsze jest zanieść to Kręgowi do zbadania. Uwierz mi – ta praca nigdzie nie ucieknie, kiedy już będzie po wszystkim. Jeśli w tym lepkim chitynie jest dziennik, Krąg w końcu uzyska wgląd w przeszłość!$B$BZanieś to archiwiście Kręgu w Nocnym Azylu. Nazywa się Umber i jest genialny. Trochę stuknięty, jasne, ale mimo to genialny! Umber ratował księgi w dużo gorszym stanie niż ta. Jeśli da się ją ocalić, on to zrobi.', 'Zanieś oblepiony przedmiot silithidów Umberowi – archiwiście Kręgu Cenariona – w wiosce Nocny Azyl w Gaju Luny.', '', '', '', '', '', '', 0),
(7521, 'plPL', 'Thunderaan Poszukiwacz Wiatru', 'Powiedziałem ci wszystko, co wiem, $N. To ty musisz zdobyć elementium. To ty musisz zniszczyć cielesną postać Władcy Ognia.$B$BZrób to, a zyskasz błogosławieństwo Thunderaana.', 'Aby uwolnić Thunderaana Poszukiwacza Wiatru z jego więzienia, musisz przekazać najwyższemu lordowi Demitrianowi prawą i lewą połowę Więzów Poszukiwacza Wiatru, 10 sztabek elementium oraz Esencję Władcy Ognia.', '', 'Wróć do najwyższego lorda Demitriana w Silithusie.', '', '', '', '', 0),
(7522, 'plPL', 'Zbadaj naczynie', 'Zbadaj naczynie jego odrodzenia, śmiertelniku. To z niego odrodzi się Poszukiwacz Wiatru!', 'Zbadaj Naczynie odrodzenia i zwróć je najwyższemu lordowi Demitrianowi.', '', '', '', '', '', '', 0),
(7561, 'plPL', '', '', 'Przekaż Uśpione ostrze muśnięte wiatrem najwyższemu lordowi Demitrianowi.', '', '', '', '', '', '', 0),
(7785, 'plPL', 'Zbadaj naczynie', 'Zbadaj naczynie jego odrodzenia, śmiertelniku. To z niego odrodzi się Poszukiwacz Wiatru!', 'Zbadaj Naczynie odrodzenia i zwróć je najwyższemu lordowi Demitrianowi.', '', '', '', '', '', '', 0),
(7786, 'plPL', 'Thunderaan Poszukiwacz Wiatru', 'Powiedziałem ci wszystko, co wiem, $N. To ty musisz zdobyć elementium. To ty musisz zniszczyć cielesną postać Władcy Ognia.$B$BZrób to, a zyskasz błogosławieństwo Thunderaana.', 'Aby uwolnić Thunderaana Poszukiwacza Wiatru z jego więzienia, musisz przekazać najwyższemu lordowi Demitrianowi w Silithusie prawą i lewą połowę Więzów Poszukiwacza Wiatru, 10 sztabek elementium oraz Esencję Władcy Ognia.', '', 'Wróć do najwyższego lorda Demitriana w Silithusie.', '', '', '', '', 0),
(7787, 'plPL', 'Powstań, Gromogniewie!', '$GPokonałeś:Pokonałaś; Poszukiwacza Wiatru. Weź uśpione ostrze i zmuś kłamliwego nędznika, Demitriana, by użył materiałów, które mu $gdostarczyłeś:dostarczyłaś; na jego zdradę, do przebudzenia Gromogniewu.', 'Przekaż Uśpione ostrze muśnięte wiatrem najwyższemu lordowi Demitrianowi.', '', '', '', '', '', '', 0),
(8277, 'plPL', 'Zabójczy jad pustyni', 'Beetix Ficklespragg do usług! Mój kuzyn Noggle zarabia na życie, zbierając rzadkie zioła dla alchemików z Twierdzy Druidów. A przynajmniej zarabiał. Z ostatniej wyprawy wrócił z silną trucizną w żyłach.$B$BUdało mi się spowolnić działanie jadu, ale żeby go całkiem zneutralizować, potrzebuję próbek trucizny od tego, co go użądliło.$B$BNoggle przybył z północy, więc dam sobie rękę uciąć, że to sprawka kamiennochłostych skorpiad albo piaskowych pędzików. Przynieś mi trochę żądeł i kłów, a spróbuję zrobić dla niego odtrutkę.', 'Beetix Ficklespragg w Twierdzy Druidów w Silithusie chce, żebyś $gzebrał:zebrała; 8 żądeł kamiennochłostych skorpiad i 8 kłów piaskowych pędzików. Wróć do niej, gdy wykonasz zadanie.', '', 'Wróć do Beetix Ficklespragg w Twierdzy Druidów w Silithusie.', '', '', '', '', 0),
(8278, 'plPL', 'Ostatnia nadzieja Noggle\'a', 'Niech to szlag! Odtrutka nie zadziałała. Noggle\'a musiało użądlić któreś z silniejszych stworzeń z dalekiego południa.$B$BMusisz się tam udać i przynieść mi więcej próbek, $N. Dobra wiadomość jest taka, że skoro ich trucizna jest silniejsza, nie będę potrzebować aż tylu. Zła – że na południu pełza więcej rodzajów jadowitych stworzeń, więc będziesz $gmusiał:musiała; czerpać z większej liczby źródeł.', 'Beetix Ficklespragg w Twierdzy Druidów w Silithusie chce, żebyś $gzebrał:zebrała; 3 żądła kamiennochłostych szczypaczy, 3 żądła kamiennochłostych obdzieraczy i 3 kły skalnych tropicieli.', '', 'Wróć do Beetix Ficklespragg w Twierdzy Druidów w Silithusie.', '', '', '', '', 0),
(8279, 'plPL', 'Leksykon Zmierzchu', 'Młot Zmierzchu nie okazuje litości tym, którzy opuszczają jego szeregi. Do dziś polują na mnie, jakbym był jakimś zwierzęciem! Nie muszę chyba dodawać, że ich wróg jest moim przyjacielem!$B$BAby rozszyfrować tę tablicę, potrzebuję księgi, której ich skrybowie używają do szyfrowania tajnych wiadomości: Leksykonu Zmierzchu. To tak ważne narzędzie, że jego trzy rozdziały przechowują w różnych miejscach! Oficerowie, którym powierzono Leksykon, zwani są Strażnikami Zmierzchu. Szukaj ich w obozach Młota Zmierzchu.', 'Przynieś trzy rozdziały Leksykonu Zmierzchu pustelnikowi Ortellowi w Silithusie.', '', 'Wróć do pustelnika Ortella w Silithusie.', '', '', '', '', 0),
(8280, 'plPL', 'Zabezpieczenie szlaków zaopatrzenia', 'Twierdza Druidów ma najwyższe znaczenie strategiczne. Jestem przekonana, że dopóki ją utrzymamy, zwycięstwo nad silithidami jest pewne. Pod warunkiem, że utrzymamy dopływ zaopatrzenia.$B$BPustynne czerwie okazały się dla naszych karawan z zaopatrzeniem większym zagrożeniem niż same silithidy. Jeszcze dziś rano grupa pogłębiarzy napastników zniszczyła duży transport jutroziarna. Przetrzeb ich, żeby nasze zaopatrzenie nie było zagrożone.', 'Przywoływaczka wiatru Dumnoroga w Twierdzy Druidów w Silithusie chce, żebyś $gzabił:zabiła; 15 pogłębiarzy napastników.', '', 'Wróć do przywoływaczki wiatru Dumnorogi w Twierdzy Druidów w Silithusie.', '', '', '', '', 0),
(8281, 'plPL', 'Wzmocnienie ochrony', 'Jak dotąd spisujesz się naprawdę wzorowo, $N. Nasze szlaki zaopatrzenia wciąż jednak nie są całkiem bezpieczne. Pod nieobecność pogłębiarzy napastników ich więksi kuzyni z południa z pewnością zajmą ich miejsce na północy.$B$BBędziesz $gmusiał:musiała; zabić sporo pogłębiarzy miażdżycieli, by trzymać ich z dala, ale nie możemy zostawić bezpieczeństwa naszych szlaków zaopatrzenia przypadkowi.', 'Przywoływaczka wiatru Dumnoroga w Twierdzy Druidów w Silithusie chce, żebyś $gzgładził:zgładziła; 20 pogłębiarzy miażdżycieli.', '', 'Wróć do przywoływaczki wiatru Dumnorogi w Roju Ashi w Silithusie.', '', '', '', '', 0),
(8282, 'plPL', 'Zgubiona sakwa Noggle\'a', 'Gdzie ja jestem? Gdzie moja torba? *wzdycha* Musiałem ją zgubić, uciekając przed Śmiertelnym Chwytem, tą olbrzymią skorpiadą. W pośpiechu wpadłem prosto w gniazdo kamiennochłostych obdzieraczy.$B$BW sakwie, którą niosłem, było mnóstwo rzadkich odczynników. Bez nich ja i Beetix nie zdołamy zrobić mikstur, których potrzebuje Twierdza Druidów. Jestem jeszcze za słaby, żeby wstać, ale dobrze ci zapłacę, jeśli przyniesiesz mi moje odczynniki.$B$BNatknąłem się na Śmiertelny Chwyt w górach na południu, za obozem Miedziobrodego.', 'Odzyskaj sakwę Noggle\'a z gór na południu Silithusu i zwróć mu ją w Twierdzy Druidów.', '', 'Wróć do Noggle\'a Ficklespragga w Twierdzy Druidów w Silithusie.', '', '', '', '', 0),
(8283, 'plPL', 'Poszukiwana: Śmiertelny Chwyt, postrach piasków', 'Uważa się, że straszliwa skorpiada zwana Śmiertelnym Chwytem wycofała się w góry na południu z powodu wzmożonej aktywności silithidów. Stanowi wielkie zagrożenie dla patroli i wypraw w regionach południowych. Osoby, które przyczynią się do jej zgładzenia, zostaną sowicie wynagrodzone. W sprawie nagrody zgłaszać się do kapitana Visha Kozusa na szczycie wieży strażniczej Twierdzy Druidów.', 'Zanieś szczypce Śmiertelnego Chwytu Vishowi Kozusowi, kapitanowi straży.', '', 'Wróć do Visha Kozusa w Twierdzy Druidów w Silithusie.', '', '', '', '', 0),
(8284, 'plPL', 'Tajemnica Zmierzchu', 'Na północny zachód stąd kwitł niegdyś obóz kultystów Młota Zmierzchu. Gdyby się tam teraz wybrać, zastałoby się okolicę roją od żywiołaków, a miejsce, gdzie stał obóz, znaczą już tylko porozrzucane kawałki drewna i płótna.$B$BOdzyskałam stamtąd kilka fragmentów glinianej tablicy, ale mam ich za mało, by złożyć z nich coś użytecznego. Sprawdź, czy zdołasz znaleźć pozostałe fragmenty tablicy, abyśmy mogli rzucić nieco światła na obecność Młota Zmierzchu tutaj, w Silithusie.', 'Geolożka Zguba Skowronków w Twierdzy Druidów w Silithusie chce, żebyś $gzebrał:zebrała; 8 fragmentów tablicy zmierzchu.', '', 'Wróć do geolożki Zguby Skowronków w Twierdzy Druidów w Silithusie.', '', '', '', '', 0),
(8285, 'plPL', 'Dezerter', 'Krążą pogłoski o członku Młota Zmierzchu imieniem Ortell, który zdezerterował ze swojej sekty. Podobno ukrył się w górach na południe od Osady Południowego Wiatru, gdzie żyje jak pustelnik. Może zdołasz go przekonać, żeby pomógł nam rozszyfrować tablicę.$B$BWeź ze sobą odnowioną tablicę i odszukaj Ortella.', 'Zanieś odnowioną tablicę pustelnikowi Ortellowi w Silithusie.$B', '', '', '', '', '', '', 0),
(8286, 'plPL', 'Co przyniesie jutro', 'Objęcia śmierci niemal całkiem mnie pochłonęły, gdy on się wmieszał. Tchnął tylko raz na moje okaleczone ciało, a potem cierpliwie czekał, aż piaski czasu oczyszczą moje rany.$B$B„Pozostaniesz na zawsze, jeśli trzeba” – rzekł, a tymi słowami zostałem związany jako Wartownik.$B$BSpójrz teraz na pustynię. Nadciąga druga wojna. Musisz odszukać miejsce spoczynku Brązowego. Udaj się do Jaskiń Czasu i sprawdź, czy pan powrócił. Muszę mieć pewność, zanim będę mógł działać dalej.', 'Udaj się do Jaskiń Czasu w Tanaris i odnajdź Anachronosa z Miotu Nozdormu.', 'Odnajdź Miot Nozdormu.', 'Wróć do Baristoltha z Ruchomych Piasków w Twierdzy Druidów w Silithusie.', '', '', '', '', 0),
(8287, 'plPL', 'Straszliwy zamysł', 'No dobrze, proszę bardzo... muszę przyznać, że całkiem cenny kawałek informacji! Widziałem, jak siły Kręgu Cenariona przybywają do Silithusu. Zamierzają wypędzić Młot Zmierzchu, prawda? To im pomoże.$B$BZanieś ten pergamin ich przywódcy, dowódcy Mar\'alithowi. Wkrótce Młot Zmierzchu zostanie pokonany, a ja na dobre wymknę się z jego szponów!', 'Zanieś pergamin z odszyfrowaną tablicą dowódcy Mar\'alithowi.', '', '', '', '', '', '', 0),
(8288, 'plPL', 'Tylko jeden może powstać', 'Nie ma czasu do stracenia! Trzeba znaleźć bohatera! Zadanie, które powierzam, wymaga armii, lecz tylko jeden spośród tłumu aspirujących czempionów może się wyłonić, by wziąć na siebie brzemię i odpowiedzialność sojusznika Miotu.$B$BW leżu Władcy Czarnej Góry żyje niezwykle okrutna bestia. Lord Miotu Lashlayer strzeże Sal Niezgody i zagradza drogę do wewnętrznego sanktuarium Nefariana. Zgładź to plugawe wynaturzenie i przynieś mi jego głowę. Zrób to, a będziesz $gmógł:mogła; rozpocząć kolejny etap swojej podróży.', 'Zanieś Głowę Lorda Miotu Lashlayera Baristolthowi z Ruchomych Piasków w Twierdzy Druidów w Silithusie.', '', 'Wróć do Baristoltha z Ruchomych Piasków w Twierdzy Druidów w Silithusie.', '', '', '', '', 0),
(8301, 'plPL', 'Ścieżka prawych', 'Miot Nozdormu z natury nie ufa pośledniejszym rasom. Choć prawdą jest, że $gdowiodłeś:dowiodłaś; mi, iż masz w sobie zadatki na bohatera, nadszedł czas, by dowieść tego mojemu panu.$B$BRój Ashi, Rój Zora, Rój Regal: wszystkie tętnią życiem i wszystkie zagrażają naszemu istnieniu. Zabijaj silithidy w tych rojach i zabieraj im fragmenty pancerzy. Gdy nie będziesz w stanie unieść więcej, wróć do mnie, a wzmocnię twoją determinację.', 'Zbierz 200 fragmentów pancerza silithida i wróć do Baristoltha.', '', 'Wróć do Baristoltha z Ruchomych Piasków w Twierdzy Druidów w Silithusie.', '', '', '', '', 0),
(8302, 'plPL', 'Ręka prawych', 'Wybieraj zastępców rozważnie, śmiertelniku. Za każdym razem, gdy wrócisz z wykonanym zadaniem, będziesz $gmógł:mogła; wybrać nowego zastępcę.$B$BA teraz potrzebuję więcej fragmentów pancerzy. Nie trać czasu!', 'Zbierz 200 fragmentów pancerza silithida i wróć do Baristoltha.', '', 'Wróć do Baristoltha z Ruchomych Piasków w Twierdzy Druidów w Silithusie.', '', '', '', '', 0),
(8304, 'plPL', 'Najdroższa Natalia', 'Moja droga Natalia zaginęła.$B$BPrawdę mówiąc, przez całe tygodnie przed zniknięciem zachowywała się dziwnie. Nie raz przyłapałem ją na tym, że mówiła do siebie, gdy nikogo nie było w pobliżu. Upierała się, że wszystko jest w porządku i że musi móc dalej prowadzić badania.$B$BOstatnio widziano ją, jak zmierzała do obozu Miedziobrodego na południu.$B$BMoich żołnierzy jest za mało, $N. Musisz udać się do obozu Miedziobrodego i przepytać te krasnoludy.', 'Dowódca Mar\'alith w Twierdzy Druidów w Silithusie chce, żebyś $gprzepytał:przepytała; mieszkańców Obozowiska Miedziobrodych. Obozowisko Miedziobrodych znajdziesz na południe od Twierdzy Druidów.$B$BGdy zbierzesz potrzebne informacje, wróć do dowódcy Mar\'alitha.', '', 'Wróć do dowódcy Mar\'alitha w Twierdzy Druidów w Silithusie.', 'Frankal przepytany', 'Rutgar przepytany', '', '', 0),
(8306, 'plPL', 'W paszczę szaleństwa', 'Musisz udać się do Roju Regal i dowiedzieć się, co się stało z moją najdroższą Natalią, $N. Nie będzie to łatwe zadanie. Zanim rzucisz się na oślep w paszczę szaleństwa, koniecznie wróć i porozmawiaj z tymi krasnoludami. Może udzielą ci wskazówek, jak sobie radzić z silithidami zamieszkującymi ten rój.$B$BI, $N, jeśli ona naprawdę jest tak obłąkana, jak mówią... zrób, co musisz.$B$B<Dowódca Mar\'alith odwraca się od ciebie.>$B', 'Dowódca Mar\'alith w Twierdzy Druidów w Silithusie chce, żebyś $godnalazł:odnalazła; jego ukochaną Natalię. Zebrane przez ciebie informacje wskazują, że panią Natalię Mar\'alith możesz znaleźć w Roju Regal na południu.$B$BNie zapomnij odwiedzić krasnoludów w obozie Miedziobrodego, zanim wyruszysz do roju. Mogą mieć dla ciebie dodatkową pracę i rady.$B$BI, $N, pamiętaj słowa dowódcy: „Zrób, co musisz...”', '', 'Wróć do dowódcy Mar\'alitha w Twierdzy Druidów w Silithusie.', 'Los pani Natalii Mar\'alith', '', '', '', 0),
(8307, 'plPL', 'Pustynny przepis', 'Przystosowanie się do życia na pustyni było, delikatnie mówiąc, trudne. Nie dość, że tęsknię za ptakami i drzewami Auberdine, to jeszcze wybór jedzenia w tym suchym klimacie jest bardzo ograniczony. Próbuję poznać pustynne zioła, ale niewiele ich tu rośnie.$B$BWidziałam, jak grupy Młota Zmierzchu z obozu na zachód stąd polują na piaskowe czerwie, żeby mieć co jeść. Mięso piaskowego czerwia jest jednak takie gorzkie, że nie wyobrażam sobie, jak robią z niego coś jadalnego. Miej oczy otwarte, jeśli pójdziesz do ich obozu, i daj mi znać, jeśli czegoś się dowiesz.', 'Poszukaj informacji o przyrządzaniu mięsa piaskowego czerwia w obozie Młota Zmierzchu na zachód od Twierdzy Druidów.', '', '', '', '', '', '', 0),
(8308, 'plPL', 'Zagubiony list Branna Miedziobrodego', 'Do wszystkich zainteresowanych:$B$BJeśli to czytasz, to albo nie żyję, albo zaraz nie będę żył. Trudno powiedzieć. Większość ekipy i tak nie żyje.$B$BZnalazłem informacje o tytanie. Wielka bitwa między nim a Przedwiecznym. Tak, prawdziwym Przedwiecznym. Znalazłem pradawny tunel prowadzący do Ahn\'Qiraj. Idę nim.$B$BZanieś ten list do mojego starego obozu. Dopilnuj, żeby moja małpka dostawała dość jedzenia, wody i przytulasów.$B$B– Brann Miedziobrody, Odkrywca Ekstremalny$B$BPS Uważajcie na szaloną nocną elfkę, która czci Przedwiecznego.', 'Zanieś list Branna Miedziobrodego do Obozowiska Miedziobrodych w południowym Silithusie.', '', '', '', '', '', '', 0),
(8309, 'plPL', 'W pogoni za glifami', 'Po naszej pierwszej wyprawie do rojów i szaleństwie, w jakie potem popadła pani Mar\'alith, z trzech rojów wylewa się robactwo! Ta wzmożona aktywność może mieć związek z glifami na tych dziwnych kryształach.$B$BMusimy zdobyć odbitki z kryształów we wszystkich trzech rojach. Jeśli je zdobędziemy, może zdołamy zrozumieć to szaleństwo.$B$BWeź ten zestaw transkrypcyjny i ruszaj do rojów, $N. Nie wracaj, dopóki nie zdobędziesz kopii z każdego roju.', 'Rutgar Glifotwórca w Obozowisku Miedziobrodych w Silithusie chce, żebyś $gudał:udała; się do Roju Ashi, Roju Zora i Roju Regal i $gzdobył:zdobyła; odbitki glifów z kryształów z glifami w każdym z rojów.$B$BUżyj zestawu transkrypcyjnego geologa, by sporządzić wierną kopię pradawnych glifów. Gdy wykonasz zadanie, wróć do Rutgara Glifotwórcy.', '', 'Wróć do Rutgara Glifotwórcy w Obozowisku Miedziobrodych w Silithusie.', '', '', '', '', 0),
(8310, 'plPL', 'Łamanie szyfru', 'Chyba potrafię opracować eliksir, dzięki któremu łatwiej odczytamy glify i język silithidów i Qiraji! Czego potrzebuję? Dobrze, że pytasz! Potrzebuję mózgów! A dokładniej: mózgu z każdego rodzaju silithidów zamieszkujących roje. Przynieś mi mózgi, a praca Rutgara może nie pójść na marne.', 'Frankal Kamienny Most w Obozowisku Miedziobrodych w Silithusie chce, żebyś $gzdobył:zdobyła; mózg silithida z Roju Zora, mózg silithida z Roju Ashi i mózg silithida z Roju Regal. Gdy wykonasz zadanie, wróć do Frankala.', '', 'Wróć do Frankala Kamiennego Mostu w Obozowisku Miedziobrodych w Silithusie.', '', '', '', '', 0),
(8313, 'plPL', 'Dzielenie się wiedzą', 'Przepis na przyrządzanie mięsa piaskowego czerwia jest czytelny, ale wspomina o ziołach i przyprawach, o których nigdy nie $gsłyszałeś:słyszałaś;. Być może Calandrath zna rośliny rosnące na pustyni na tyle dobrze, by go zrozumieć.', 'Zanieś wydartą kartkę z przepisem Calandrath w gospodzie w Twierdzy Druidów.', '', '', '', '', '', '', 0),
(8314, 'plPL', 'Rozwikłanie tajemnicy', 'Jesteśmy o krok od przełomu, $N! Dzięki odbitkom, które $gprzyniosłeś:przyniosłaś;, odtworzyliśmy glify na tym krystalicznym pryzmacie. Najwyraźniej służą one Qiraji i innym nieznanym istotom do przekazywania silithidom różnych wiadomości.$B$BNiestety, nic więcej z glifów nie wyczytaliśmy. Musimy znaleźć sposób, by odblokować wiadomości ukryte w kryształach.$B$BZanieś kryształowy pryzmat z glifami geolożce Zgubie Skowronków w Twierdzy Druidów. Może ona zdoła pomóc.', 'Rutgar Glifotwórca z Obozowiska Miedziobrodych chce, żebyś $gdostarczył:dostarczyła; kryształowy pryzmat z glifami geolożce Zgubie Skowronków w Twierdzy Druidów w Silithusie.', '', '', '', '', '', '', 0),
(8315, 'plPL', 'Wezwanie', 'Glify przedstawiają wysłannika Qiraji, który spotyka się z trzema silithidami przy kościach wielkiego smoka. Nad glifami jest coś, co mogę uznać jedynie za jakiś kod. Ten kod może być kluczem do przywołania wysłannika.$B$BSporządzę kopię kodu glifów, którą musisz nakreślić na piasku przy Kościach Grakkaronda. Jeśli mam rację, przybędą Nadrządcy, sądząc, że nowe dane są gotowe do przekazania. Zabij ich i stań do walki z wysłannikiem. To on ma klucz do kryształów...', 'Geolożka Zguba Skowronków w Twierdzy Druidów w Silithusie chce, żebyś $godebrał:odebrała; kryształowy mechanizm otwierający wysłannikowi Qiraji.$B$BPolecono ci zanieść Glify wezwania do Kości Grakkaronda na południe od Twierdzy Druidów i nakreślić je na piasku. Jeśli pojawi się wysłannik Qiraji, zabij go i zabierz kryształowy mechanizm otwierający. Jeśli ci się powiedzie, wróć do geolożki Zguby Skowronków.$B$BZbierz armię do tego zadania, $N!', '', 'Wróć do geolożki Zguby Skowronków w Twierdzy Druidów w Silithusie.', '', '', '', '', 0),
(8316, 'plPL', 'Uzbrojenie wojenne', '', '', '', '', '', '', '', '', 0),
(8317, 'plPL', 'Pomoc w kuchni', 'Ten przepis na pewno się przyda. Lepiej wezmę się do pracy, żeby mieć na dziś trochę wędzonych pustynnych pierożków. Przydałaby mi się pomoc przy ich robieniu, nie pożałujesz.', 'Calandrath w Twierdzy Druidów potrzebuje 10 wędzonych pustynnych pierożków.', '', 'Wróć do Calandrath w Twierdzy Druidów w Silithusie.', '', '', '', '', 0),
(8318, 'plPL', 'Tajna korespondencja', 'Niektórzy kultyści Młota Zmierzchu noszą przy sobie karteczki z bełkotem. Przynieś mi ich cały plik, $N.$B$BNie umiem odgadnąć, co ten bełkot znaczy, ale nie o to chodzi! Za pomocą tych kartek ich różne grupy potajemnie się porozumiewają. Im więcej tekstów wycofamy z obiegu, tym mniej będą mogli się porozumiewać!', 'Przynieś 10 zaszyfrowanych tekstów Zmierzchu Borowi Dzikogrzywemu w Twierdzy Druidów.', '', 'Wróć do Bora Dzikogrzywego w Roju Ashi w Silithusie.', '', '', '', '', 0),
(8319, 'plPL', 'Zaszyfrowane teksty Zmierzchu', '', '', '', 'Wróć do Bora Dzikogrzywego w Silithusie.', '', '', '', '', 0),
(8320, 'plPL', 'Geowładcy Zmierzchu', 'Młot Zmierzchu, obłąkany kult żądny zniszczenia, rozbił w Silithusie obozy i dzień i noc odprawia w nich rytuały. Nie znamy jeszcze ich planów, ale sądzimy, że mają one jakiś związek z pulsującymi czerwonymi kryształami rozsianymi po pustyni.$B$BChoć ich tajemnica może pewnego dnia zostać rozwikłana, najpierw musimy się zająć bezpośrednim zagrożeniem. Udaj się do ich obozów na zachodzie i odszukaj geowładców Zmierzchu. To głowy tych węży; tam musimy uderzyć!', 'Zabij 10 geowładców Zmierzchu, a następnie wróć do Huuma Dzikogrzywego w Twierdzy Druidów.', '', 'Wróć do Huuma Dzikogrzywego w Twierdzy Druidów w Silithusie.', '', '', '', '', 0),
(8321, 'plPL', 'Vyral Plugawy', 'Odkryliśmy kolejną bazę operacyjną Młota Zmierzchu. Nazywa się Szlak Zmierzchu; to jaskinia ukryta w północno-wschodnim zakątku Silithusu. W tej jaskini przebywa miejscowy przywódca kultu, Vyral Plugawy – to jego musisz teraz pokonać. Kiedy to zrobisz, przynieś mi jego sygnet.$B$BPowodzenia, $N. Okropności Szlaku Zmierzchu są doprawdy groźne.', 'Przynieś sygnet Vyrala Huumowi Dzikogrzywemu w Twierdzy Druidów.', '', 'Wróć do Huuma Dzikogrzywego w Twierdzy Druidów w Silithusie.', '', '', '', '', 0),
(8323, 'plPL', 'Prawdziwi wyznawcy', 'Teraz, gdy mam Leksykon Zmierzchu, chciałbym cię prosić o drobną przysługę.$B$BMoja dawna organizacja co miesiąc rozsyła tajny, zaszyfrowany biuletyn.$B$BJeśli poczynią jakieś postępy w poszukiwaniach mnie albo je odwołają, wieść o tym ukaże się w „Prawdziwym Wyznawcy”.$B$BChoć te informacje są dla mnie oczywiście cenne, biuletyn zawiera też inne przydatne wiadomości, którymi mogę się podzielić. Przynoś mi wszelkie zaszyfrowane teksty, które znajdziesz przy członkach Młota Zmierzchu.', 'Pustelnik Ortell chce, żebyś $gprzyniósł:przyniosła; mu 10 zaszyfrowanych tekstów Zmierzchu.', '', 'Wróć do pustelnika Ortella w Silithusie.', '', '', '', '', 0),
(8324, 'plPL', 'Wciąż wierni', '', '', '', 'Wróć do pustelnika Ortella w Silithusie.', '', '', '', '', 0),
(8331, 'plPL', 'Aurel Złoty Liść', '$N, choć mieliśmy nadzieję, że działania Młota Zmierzchu w Silithusie słabną... niestety, myliliśmy się. Dzięki kolejnym wypadom przeciw kultowi dowiedzieliśmy się, że jeszcze mroczniejsza potęga, Abisalna Rada, kontroluje Młot za pomocą tajemnych Kamieni Wiatru rozsianych po obozach kultu. Twoje następne działanie, $N, będzie wymierzone w Abisalną Radę.$B$BPorozmawiaj z rzemieślniczką Aurel Złotym Liściem we wschodniej części Twierdzy Druidów. Jej umiejętności będą potrzebne w tym kolejnym gambicie.', 'Porozmawiaj z Aurel Złotym Liściem w Twierdzy Druidów.', '', '', '', '', '', '', 0),
(8332, 'plPL', 'Książęta Rady', 'Sądzimy, że da się użyć Kamienia Wiatru, by zastawić zasadzkę na księcia Abisalnej Rady. Trzeba jednak porozumieć się przez Kamień Wiatru i przekonać radę, że jest się przywódcą średniej rangi w Młocie Zmierzchu.$B$BTaki gambit wymaga repliki medalionu rangi kultu. Mogę wykonać medalion, ale potrzebuję dużego lśniącego odłamka i herbów noszonych przez abisalnych templariuszy.$B$BPrzynieś mi je, a resztą zajmę się ja.', 'Przynieś 1 duży lśniący odłamek i 3 abisalne herby Aurel Złotemu Liściowi w Twierdzy Druidów.', '', 'Wróć do Aurel Złotego Liścia w Twierdzy Druidów w Silithusie.', '', '', '', '', 0),
(8333, 'plPL', 'Medalion rangi', '', '', '', 'Wróć do Aurel Złotego Liścia w Silithusie.', '', '', '', '', 0),
(8339, 'plPL', 'Władcy Rady <NYI> <TXT> UNUSED', 'Do zrobienia sygnetu kultysty Zmierzchu potrzeba mi sporo przedmiotów', 'Zanieś przedmioty Aurelowi Złotemu Liściowi w Twierdzy Druidów.', '', '', '', '', '', '', 0),
(8340, 'plPL', 'Sygnet Zmierzchu <NYI> <TXT>', '', '', '', '', '', '', '', '', 0),
(8341, 'plPL', 'Lordowie Rady', 'Lordów Abisalnej Rady można przywołać tylko za pomocą Większych Kamieni Wiatru i tylko najwyżsi rangą członkowie Rady Zmierzchu mogą z nimi rozmawiać. Ale... znalazłam sposób, by ulepszyć twoje przebranie i oszukać Abisalnych Lordów!$B$BDo przebrania potrzebny jest pierścień władzy, noszony tylko przez najwyższych członków kultu. Wykonam go dla ciebie, jeśli przyniesiesz mi duże lśniące odłamki i abisalne sygnety.', 'Przynieś 5 dużych lśniących odłamków i 3 abisalne sygnety Aurel Złotemu Liściowi w Twierdzy Druidów.', '', 'Wróć do Aurel Złotego Liścia w Twierdzy Druidów w Silithusie.', '', '', '', '', 0),
(8342, 'plPL', 'Pierścień władzy Zmierzchu', '', '', '', 'Wróć do Aurel Złotego Liścia w Silithusie.', '', '', '', '', 0),
(8343, 'plPL', 'Odkrycie Aurel Złotego Liścia', '$N, Aurel Złoty Liść sądzi, że znalazła sposób, by przywołać i pokonać jednego z rządzących członków Abisalnej Rady! To zadanie będzie niebezpieczne, ale $gzyskałeś:zyskałaś; wielki szacunek w Kręgu Cenariona. Wiemy, że jeśli ktokolwiek może tego dokonać, to właśnie ty.$B$BNiech szczęście ci sprzyja, $N. Porozmawiaj z Aurel, kiedy będziesz $ggotów:gotowa;.', 'Porozmawiaj z Aurel Złotym Liściem w Twierdzy Druidów.', '', '', '', '', '', '', 0),
(8348, 'plPL', 'Sygnet książąt', 'Huum mówi, że $godkryłeś:odkryłaś;, jak przywołać Abisalnych Książąt! To nie lada osiągnięcie.$B$BWiesz, co jeszcze byłoby nie lada osiągnięciem? Porządnie sprać jednego z nich. To zrobi wrażenie na ich podwładnych, jeśli wiesz, co mam na myśli. Przynieś jego sygnet jako dowód.', 'Przynieś abisalny sygnet Borowi Dzikogrzywemu w Twierdzy Druidów.', '', 'Wróć do Bora Dzikogrzywego w Roju Ashi w Silithusie.', '', '', '', '', 0),
(8349, 'plPL', 'Bor Dzikogrzywy', 'Teraz, gdy masz medalion i możesz przywołać Abisalnego Księcia, porozmawiaj z Borem Dzikogrzywym. Wyznaczy ci zadanie przeciw Abisalnej Radzie.$B$BPowodzenia, $N. A jeśli kiedyś będziesz potrzebować więcej medalionów, wróć do mnie.', 'Porozmawiaj z Borem Dzikogrzywym w Twierdzy Druidów.', '', '', '', '', '', '', 0),
(8351, 'plPL', 'Bor chce porozmawiać', 'Teraz, gdy możesz się przebrać za rządzącego członka Rady Zmierzchu, jestem pewna, że Bor Dzikogrzywy zechce z tobą porozmawiać. Idź do niego i przygotuj się na bardzo trudną misję...', 'Porozmawiaj z Borem Dzikogrzywym w Twierdzy Druidów.', '', '', '', '', '', '', 0),
(8352, 'plPL', 'Berło Rady', 'Właśnie rozmawialiśmy z Huumem o tobie. Mówi, że jesteś już prawie $ggotów:gotowa;, by spróbować sił w walce z Abisalnym Lordem!$B$BMuszę ci powiedzieć, że to bardzo niebezpieczne przedsięwzięcie. Lepiej weź wsparcie. I nie mówię o jednym czy dwóch przyjaciołach, tylko o pierwszorzędnym, gotowym do bitwy oddziale. Jeśli twoi przyjaciele są tak dobrzy jak ty, może nawet go pokonacie!$B$BJeśli wam się uda – a jak zawsze będę chciał dowodu – dam ci naprawdę wspaniałą nagrodę.', 'Przynieś abisalne berło Borowi Dzikogrzywemu w Twierdzy Druidów.', '', 'Wróć do Bora Dzikogrzywego w Roju Ashi w Silithusie.', '', '', '', '', 0),
(8361, 'plPL', 'Abisalne kontakty', 'Widzieliśmy, jak kultyści Młota Zmierzchu odprawiają rytuały, by przywołać potężnych żywiołaczych możnych. Nie wiemy, czy to istoty, które kultyści czczą, czy też pośredniczą one w kontaktach z jeszcze potężniejszymi siłami. Jedno jest pewne: kultyści dostają od tych żywiołaków rozkazy.$B$BZnajdź sposób, by skontaktować się z abisalnym templariuszem i porządnie go sprać! Nic tak nie wprowadza zamętu w szeregach jak rozbicie łańcucha dowodzenia. Przy okazji przynieś dowód.', 'Bor Dzikogrzywy w Twierdzy Druidów w Silithusie chce, żebyś $gzniszczył:zniszczyła; abisalnego templariusza i $gprzyniósł:przyniosła; mu abisalny herb jako dowód.', '', 'Wróć do Bora Dzikogrzywego w Roju Ashi w Silithusie.', '', '', '', '', 0),
(8362, 'plPL', 'Abisalne herby', '', '', '', 'Wróć do Bora Dzikogrzywego w Silithusie.', '', '', '', '', 0),
(8363, 'plPL', 'Abisalne sygnety', '', '', '', 'Wróć do Bora Dzikogrzywego w Silithusie.', '', '', '', '', 0),
(8364, 'plPL', 'Abisalne berła', '', '', '', 'Wróć do Bora Dzikogrzywego w Silithusie.', '', '', '', '', 0),
(8376, 'plPL', 'Uzbrojenie wojenne', '', '', '', '', '', '', '', '', 0),
(8377, 'plPL', 'Uzbrojenie wojenne', '', '', '', '', '', '', '', '', 0),
(8378, 'plPL', 'Uzbrojenie wojenne', '', '', '', '', '', '', '', '', 0),
(8379, 'plPL', 'Uzbrojenie wojenne', '', '', '', '', '', '', '', '', 0),
(8380, 'plPL', 'Uzbrojenie wojenne', '', '', '', '', '', '', '', '', 0),
(8381, 'plPL', 'Uzbrojenie wojenne', '', '', '', '', '', '', '', '', 0),
(8382, 'plPL', 'Uzbrojenie wojenne', '', '', '', '', '', '', '', '', 0),
(8444, 'plPL', '<NYI> <TXT> Rozmowa z Cieniem Bursztynowego Księżyca', '', '', '', '', '', '', '', '', 0),
(8445, 'plPL', '<NYI> <TXT> Rozmowa z Cieniem Bursztynowego Księżyca', '', '', '', '', '', '', '', '', 0),
(8496, 'plPL', 'Bandaże na pole bitwy', 'Po niedawnych stratach nasze zapasy bandaży na polu bitwy są niebezpiecznie niskie. Zdobądź partię środków pierwszej pomocy i dostarcz je przywoływaczce wiatru Dumnorodze w Twierdzy Druidów.', 'Przynieś 30 ciężkich bandaży z runicznej tkaniny, 30 ciężkich jedwabnych bandaży i 30 ciężkich bandaży z tkaniny magów przywoływaczce wiatru Dumnorodze w Twierdzy Druidów w Silithusie. Aby ukończyć to zadanie, musisz też przynieść Instrukcję zadania logistycznego X.', '', 'Wróć do przywoływaczki wiatru Dumnorogi w Twierdzy Druidów w Silithusie.', '', '', '', '', 0),
(8497, 'plPL', 'Pustynne zestawy przetrwania', 'Wraz z przybyciem do Twierdzy Druidów świeżych rekrutów pojawia się problem, jak utrzymać ich przy życiu na pustyni. Odwodnienie i liczne jadowite stworzenia stanowią poważne zagrożenie dla niedoświadczonych ochotników. Zbierz zapasy potrzebne do pustynnego zestawu przetrwania i zanieś je Calandrath w Twierdzy Druidów.', 'Przynieś 4 kule wody, 4 potężne odtrutki i 4 wędzone pustynne pierożki Calandrath w gospodzie w Twierdzy Druidów w Silithusie. Aby ukończyć to zadanie, musisz też przynieść Instrukcję zadania logistycznego I.', '', 'Wróć do Calandrath w Twierdzy Druidów w Silithusie.', '', '', '', '', 0),
(8498, 'plPL', 'Rozkazy bojowe Zmierzchu', 'Nasi zwiadowcy donoszą, że przywódcy Młota Zmierzchu wydają nowe rozkazy bojowe. Rozkazy rozprowadzają prorokinie Zmierzchu pod silną eskortą. Przechwyć rozkazy i zanieś je dowódcy Mar\'alithowi.', 'Zdobądź Rozkazy bojowe Zmierzchu i zanieś je dowódcy Mar\'alithowi w Twierdzy Druidów w Silithusie. Aby ukończyć to zadanie, musisz też przynieść Instrukcję zadania taktycznego X.', '', 'Wróć do dowódcy Mar\'alitha w Twierdzy Druidów w Silithusie.', '', '', '', '', 0),
(8501, 'plPL', 'Cel: żądlarze z Roju Ashi', 'W miarę rozwoju działań wojennych obecność silithidów w okolicy coraz bardziej zagraża naszym operacjom. $GZostałeś wybrany:Zostałaś wybrana; do udziału w szturmie na Rój Ashi, gdzie twoim głównym celem będą latający żądlarze z Roju Ashi.$B$BPo wykonaniu zadania zamelduj się u dowódcy Mar\'alitha.', 'Zabij 30 żądlarzy z Roju Ashi i zamelduj się u dowódcy Mar\'alitha w Twierdzy Druidów w Silithusie. Aby ukończyć to zadanie, musisz też przynieść Instrukcję zadania bojowego XII.$B', '', 'Wróć do dowódcy Mar\'alitha w Twierdzy Druidów w Silithusie.', '', '', '', '', 0),
(8502, 'plPL', 'Cel: robotnicy z Roju Ashi', 'W miarę rozwoju działań wojennych obecność silithidów w okolicy coraz bardziej zagraża naszym operacjom. $GZostałeś wybrany:Zostałaś wybrana; do udziału w szturmie na Rój Ashi, gdzie twoim głównym celem będą robotnicy z Roju Ashi.$B$BPo wykonaniu zadania zamelduj się u dowódcy Mar\'alitha.', 'Zgładź 30 robotników z Roju Ashi i zamelduj się u dowódcy Mar\'alitha w Twierdzy Druidów w Silithusie. Aby ukończyć to zadanie, musisz też przynieść Instrukcję zadania bojowego III.', '', 'Wróć do dowódcy Mar\'alitha w Twierdzy Druidów w Silithusie.', '', '', '', '', 0),
(8507, 'plPL', 'Służba polowa', 'Witaj, $N. Zanim przydzielę ci poważniejsze zadania w tej wojnie, musisz odsłużyć swoje w służbie polowej.$B$BBrygadę Żelaznej Kuźni kapitana Czarne Kowadło znajdziesz pod Rojem Zora.$B$BZamelduj się u niego albo u jego porucznik, Janeli Mocnomłot, i wróć do mnie. Przygotuję dla ciebie bardziej zaawansowany przydział.$B$BI zrób nam przysługę: trzymaj się z dala od Legionu Orgrimmaru. Z powodu wzajemnej wrogości musimy trzymać oba oddziały z dala od siebie.', 'Zamelduj się na służbę na posterunku Brygady Żelaznej Kuźni w pobliżu Roju Zora. Przygotuj niepodpisane dokumenty służby polowej, zdobądź podpisane dokumenty służby polowej od kapitana Czarne Kowadło i wróć do przywoływacza wiatru Kaldona w Twierdzy Druidów w Silithusie.$B$BUwaga: leczenie członków Brygady Żelaznej Kuźni lub rzucanie na nich korzystnych zaklęć oznaczy cię do PvP.', '', 'Wróć do przywoływacza wiatru Kaldona w Twierdzy Druidów w Silithusie.', '', '', '', '', 0),
(8508, 'plPL', 'Dokumenty służby polowej', '', '', '', 'Wróć do kapitana Czarne Kowadło w Silithusie.', '', '', '', '', 0),
(8534, 'plPL', 'Raport zwiadowczy z Roju Zora', 'Wysłaliśmy naszych najlepszych zwiadowców w głąb silithidzkich rojów, by zebrali informacje. Zwiadowca Azenel od kilku dni obserwuje ruchy silithidów w Roju Zora. Odszukaj zwiadowcę i zdobądź pisemny raport. Musimy móc jak najszybciej wykorzystać te informacje, $N.', 'Skontaktuj się z cenariońskim zwiadowcą Azenel w Roju Zora i zanieś raport zwiadowczy z Roju Zora przywoływaczce wiatru Dumnorodze w Twierdzy Druidów. Aby ukończyć to zadanie, musisz też przynieść Instrukcję zadania taktycznego VI.', '', 'Wróć do przywoływaczki wiatru Dumnorogi w Twierdzy Druidów w Silithusie.', '', '', '', '', 0),
(8535, 'plPL', 'Siwy templariusz', 'Młot Zmierzchu i żywiołaczy możni, których czci, stanowią poważne zagrożenie dla naszych operacji w Silithusie. Wobec nowych wrogów, z którymi mierzymy się w Ahn\'Qiraj, nie możemy sobie pozwolić na opuszczenie gardy przed wrogami na zewnątrz.$B$BZnajdź sposób, by przywołać i zniszczyć siwego templariusza, i zamelduj się u Bora Dzikogrzywego.$B', 'Przywołaj i zgładź siwego templariusza, a następnie zamelduj się u Bora Dzikogrzywego w Twierdzy Druidów. Aby ukończyć to zadanie, musisz też przynieść Instrukcję zadania taktycznego IV.', '', 'Wróć do Bora Dzikogrzywego w Twierdzy Druidów w Silithusie.', '', '', '', '', 0),
(8536, 'plPL', 'Ziemny templariusz', 'Młot Zmierzchu i żywiołaczy możni, których czci, stanowią poważne zagrożenie dla naszych operacji w Silithusie. Wobec nowych wrogów, z którymi mierzymy się w Ahn\'Qiraj, nie możemy sobie pozwolić na opuszczenie gardy przed wrogami na zewnątrz.$B$BZnajdź sposób, by przywołać i zniszczyć ziemnego templariusza, i zamelduj się u Bora Dzikogrzywego.', 'Przywołaj i zgładź ziemnego templariusza, a następnie zamelduj się u Bora Dzikogrzywego w Twierdzy Druidów. Aby ukończyć to zadanie, musisz też przynieść Instrukcję zadania taktycznego III.', '', 'Wróć do Bora Dzikogrzywego w Twierdzy Druidów w Silithusie.', '', '', '', '', 0),
(8537, 'plPL', 'Karmazynowy templariusz', 'Młot Zmierzchu i żywiołaczy możni, których czci, stanowią poważne zagrożenie dla naszych operacji w Silithusie. Wobec nowych wrogów, z którymi mierzymy się w Ahn\'Qiraj, nie możemy sobie pozwolić na opuszczenie gardy przed wrogami na zewnątrz.$B$BZnajdź sposób, by przywołać i zniszczyć karmazynowego templariusza, i zamelduj się u Bora Dzikogrzywego.', 'Przywołaj i zgładź karmazynowego templariusza, a następnie zamelduj się u Bora Dzikogrzywego w Twierdzy Druidów. Aby ukończyć to zadanie, musisz też przynieść Instrukcję zadania taktycznego II.', '', 'Wróć do Bora Dzikogrzywego w Twierdzy Druidów w Silithusie.', '', '', '', '', 0),
(8538, 'plPL', 'Czterej książęta', 'Powiązania między Młotem Zmierzchu a Abisalną Radą okazują się ważniejsze, niż się spodziewaliśmy.$B$BSądzimy, że żywiołaczy możni zwani Abisalnymi Książętami są jedną z głównych sił organizujących kultystów Młota Zmierzchu. Znajdź sposób, by zwabić czterech Abisalnych Książąt na nasz plan istnienia, i zniszcz ich!$B$BTwoje oddanie i sprawność w poprzednich przydziałach sprawiły, że to właśnie ciebie wybraliśmy do tego zadania. Jesteśmy pewni, że ci się powiedzie.', 'Znajdź sposób, by przywołać i zgładzić Księcia Popiołów, Księcia Głębin, Księcia Zefirów i Księcia Odłamków, a następnie zamelduj się u dowódcy Mar\'alitha w Twierdzy Druidów. Aby ukończyć to zadanie, musisz też przynieść Instrukcję zadania taktycznego V.', '', 'Wróć do dowódcy Mar\'alitha w Twierdzy Druidów w Silithusie.', '', '', '', '', 0),
(8539, 'plPL', 'Cel: siostry z Roju Zora', 'Wezwano posiłki, by dołączyły do szturmu na Rój Zora. $GZostałeś wybrany:Zostałaś wybrana;, by zająć się siostrami z Roju Zora. Po wykonaniu zadania zamelduj się u dowódcy Mar\'alitha.', 'Zgładź 30 sióstr z Roju Zora i zamelduj się u dowódcy Mar\'alitha w Twierdzy Druidów w Silithusie. Aby ukończyć to zadanie, musisz też przynieść Instrukcję zadania bojowego V.', '', 'Wróć do dowódcy Mar\'alitha w Twierdzy Druidów w Silithusie.', '', '', '', '', 0),
(8540, 'plPL', 'Buty dla straży', 'Konnemu oddziałowi straży Twierdzy Druidów brakuje zdobionych mithrilowych butów. Zdobądź partię i natychmiast dostarcz ją kapitanowi Vishowi Kozusowi w Twierdzy Druidów.', 'Przynieś 3 pary zdobionych mithrilowych butów Vishowi Kozusowi, kapitanowi straży w Twierdzy Druidów w Silithusie. Aby ukończyć to zadanie, musisz też przynieść Instrukcję zadania logistycznego II.', '', 'Wróć do Visha Kozusa w Twierdzy Druidów w Silithusie.', '', '', '', '', 0),
(8541, 'plPL', 'Kamienie szlifierskie dla straży', 'Straży Twierdzy Druidów brakuje kamieni szlifierskich. Zdobądź partię i natychmiast dostarcz ją kapitanowi Vishowi Kozusowi w Twierdzy Druidów.', 'Przynieś 10 gęstych kamieni szlifierskich, 10 solidnych kamieni szlifierskich i 10 ciężkich kamieni szlifierskich Vishowi Kozusowi, kapitanowi straży w Twierdzy Druidów w Silithusie. Aby ukończyć to zadanie, musisz też przynieść Instrukcję zadania logistycznego III.', '', 'Wróć do Visha Kozusa w Twierdzy Druidów w Silithusie.', '', '', '', '', 0),
(8548, 'plPL', 'Rynsztunek ochotnika', 'Odznaki, które zbierasz, wykonując przydziały bojowe, logistyczne i taktyczne dla Twierdzy Druidów, to coś więcej niż ozdoba, $N.$B$BRozsądnie byłoby je zachować. Gdy dowiedziesz swojej lojalności wobec naszej organizacji, w zamian za te odznaki mogę ci zaoferować część ekwipunku, który zachowujemy dla naszych najbliższych sojuszników.', 'Przynieś 5 cenariońskich odznak bojowych, 3 cenariońskie odznaki logistyczne i 7 cenariońskich odznak taktycznych Vargusowi w Twierdzy Druidów w Silithusie. Aby ukończyć to zadanie, musisz też zdobyć u Kręgu Cenariona reputację na poziomie Przyjazny.', '', 'Wróć do Vargusa w Twierdzy Druidów w Silithusie.', '', '', '', '', 0),
(8556, 'plPL', 'Sygnet nieustępliwej siły', 'Podobno pierścienie noszone przez qirajskich poruczników dają im groźne zdolności. Zdobiące je skażone klejnoty można by w teorii zastąpić czystszymi materiałami i stworzyć nieskażone wersje pierścieni.$B$BKlejnoty zdobiące idole Qiraji nadałyby się świetnie, bo są wyższej jakości.$B$BPrzynieś mi pierścień i idole, a stworzę dla ciebie potężny pierścień, $N.', 'Przynieś 1 magisterski pierścień Qiraji, 2 lśniące idole, 5 brązowych skarabeuszy i 5 skarabeuszy z kości słoniowej przywoływaczce wiatru Yessendrze w Silithusie. Aby ukończyć to zadanie, musisz też zdobyć u Kręgu Cenariona reputację na poziomie Szanowany.', '', 'Wróć do przywoływaczki wiatru Yessendry w Roju Ashi w Silithusie.', '', '', '', '', 0),
(8557, 'plPL', 'Opończa nieustępliwej siły', 'Cieszę się, że pomagasz nam w ataku na Ahn\'Qiraj, $N. Mogę zrobić dla ciebie przedmiot ochronny, który przyda się w walce z naszym wrogiem.$B$BBędę potrzebować opończy Qiraji, którą oczywiście dopasuję do ciebie. Potrzebuję też idoli i skarabeuszy, z których zrobię odpowiednią zapinkę.$B$BObiecuję, że się nie zawiedziesz.', 'Przynieś 1 wojenną opończę Qiraji, 2 onyksowe idole, 5 srebrnych skarabeuszy i 5 kościanych skarabeuszy Keylowi Rączemu Szponowi w Silithusie. Aby ukończyć to zadanie, musisz też zdobyć u Kręgu Cenariona reputację na poziomie Czczony.', '', 'Wróć do Keyla Rączego Szponu w Roju Ashi w Silithusie.', '', '', '', '', 0),
(8558, 'plPL', 'Sierp nieustępliwej siły', 'Qiraji i ich słudzy dzierżą przedmioty z najrzadszych i najprzedniejszych materiałów: kości olbrzymich pradawnych stworzeń, klejnotów z głębi ziemi, czystych i mocnych metali.$B$BSam widok artefaktów Qiraji budzi we mnie chęć, by ćwiczyć swoje rzemiosło na ich roztrzaskanych i przetopionych kawałkach. Dowiedź swojej wierności Kręgowi, $N, a wykonam dla ciebie potężną broń z najprzedniejszych materiałów Qiraji.', 'Przynieś 1 kolczastą rękojeść Qiraji, 2 alabastrowe idole, 5 kryształowych skarabeuszy i 5 kamiennych skarabeuszy strażnikowi Haro w Silithusie. Aby ukończyć to zadanie, musisz też zdobyć u Kręgu Cenariona reputację na poziomie Wywyższony.', '', 'Wróć do strażnika Haro w Roju Ashi w Silithusie.', '', '', '', '', 0),
(8572, 'plPL', 'Rynsztunek weterana', 'Odznaki, które zbierasz, wykonując przydziały bojowe, logistyczne i taktyczne dla Twierdzy Druidów, to coś więcej niż ozdoba, $N.$B$BRozsądnie byłoby je zachować. Gdy dowiedziesz swojej lojalności wobec naszej organizacji, w zamian za te odznaki mogę ci zaoferować część ekwipunku, który zachowujemy dla naszych najbliższych sojuszników.', 'Przynieś 7 cenariońskich odznak bojowych, 4 cenariońskie odznaki logistyczne i 4 cenariońskie odznaki taktyczne Vargusowi w Twierdzy Druidów w Silithusie. Aby ukończyć to zadanie, musisz też zdobyć u Kręgu Cenariona reputację na poziomie Szanowany.$B', '', 'Wróć do Vargusa w Twierdzy Druidów w Silithusie.', '', '', '', '', 0),
(8573, 'plPL', 'Rynsztunek czempiona', 'Odznaki, które zbierasz, wykonując przydziały bojowe, logistyczne i taktyczne dla Twierdzy Druidów, to coś więcej niż ozdoba, $N.$B$BRozsądnie byłoby je zachować. Gdy dowiedziesz swojej lojalności wobec naszej organizacji, w zamian za te odznaki mogę ci zaoferować część ekwipunku, który zachowujemy dla naszych najbliższych sojuszników.', 'Przynieś 15 cenariońskich odznak bojowych, 20 cenariońskich odznak logistycznych, 20 cenariońskich odznak taktycznych i 1 Znak Cenariusa Vargusowi w Twierdzy Druidów w Silithusie. Aby ukończyć to zadanie, musisz też zdobyć u Kręgu Cenariona reputację na poziomie Wywyższony.$B', '', 'Wróć do Vargusa w Twierdzy Druidów w Silithusie.', '', '', '', '', 0),
(8574, 'plPL', 'Rynsztunek niezłomnego', 'Odznaki, które zbierasz, wykonując przydziały bojowe, logistyczne i taktyczne dla przywoływaczki wiatru Dumnorogi, to coś więcej niż ozdoba, $N.$B$BRozsądnie byłoby je zachować. Gdy dowiedziesz swojej lojalności wobec naszej organizacji, w zamian za te odznaki mogę ci zaoferować część ekwipunku, który zachowujemy dla naszych najbliższych sojuszników.', 'Przynieś 15 cenariońskich odznak bojowych, 20 cenariońskich odznak logistycznych, 17 cenariońskich odznak taktycznych i 1 Znak Remulosa Vargusowi w Twierdzy Druidów w Silithusie. Aby ukończyć to zadanie, musisz też zdobyć u Kręgu Cenariona reputację na poziomie Czczony.', '', 'Wróć do Vargusa w Twierdzy Druidów w Silithusie.', '', '', '', '', 0),
(8654, 'plPL', 'Nestor Pierwokamień', '', '', '', '', '', '', '', '', 0),
(8687, 'plPL', 'Cel: tunelarze z Roju Zora', 'Wezwano posiłki, by dołączyły do szturmu na Rój Zora. $GZostałeś wybrany:Zostałaś wybrana;, by zająć się tunelarzami z Roju Zora. Po wykonaniu zadania zamelduj się u dowódcy Mar\'alitha.', 'Zgładź 30 tunelarzy z Roju Zora i zamelduj się u dowódcy Mar\'alitha w Twierdzy Druidów w Silithusie. Aby ukończyć to zadanie, musisz też przynieść Instrukcję zadania bojowego VII.$B', '', 'Wróć do dowódcy Mar\'alitha w Twierdzy Druidów w Silithusie.', '', '', '', '', 0),
