(8541, 'plPL', 'Masz coś dla mnie, $N?', 0),
(8542, 'plPL', 'Pogłębiarze napastnicy to poważne zagrożenie i trzeba się z nimi szybko rozprawić!', 0),
(8548, 'plPL', 'W naszym najlepszym interesie jest, by nasi najwierniejsi sojusznicy byli dobrze wyposażeni, $N.', 0),
