(8731, 'plPL', '$GOdbyłeś:Odbyłaś; już służbę polową, $N? Kapitana Czaszkołupa znajdziesz pod Rojem Regal.', 0),
(8732, 'plPL', 'Rozumiem, że chcesz podpisać te dokumenty, $Gchłopcze:dziewczyno;?', 0),
(8737, 'plPL', '$GWykonałeś:Wykonałaś; już zadanie, $N?', 0),
(8738, 'plPL', 'Zwiadowcę Landiona znajdziesz w Roju Regal. Pośpiesz się, $N! Czas nagli.', 0),
(8739, 'plPL', 'Zwiadowcę Jalię znajdziesz w Roju Ashi. Pośpiesz się, $N! Czas nagli.', 0),
(8740, 'plPL', '$GWykonałeś:Wykonałaś; już zadanie, $N?', 0),
(8743, 'plPL', 'Gong Skarabeusza góruje przed tobą złowieszczo. Przygotuj się, $N; gdy tylko zabrzmi Gong Skarabeusza, wrota Ahn\'Qiraj zostaną otwarte.$B$BZ rozwartej paszczy bestii może wyjść tylko chaos i zniszczenie. Broń swojego ludu!', 0),
(8770, 'plPL', 'Masz mi coś do powiedzenia, $N?', 0),
