(8786, 'plPL', 'Masz coś dla mnie, $N?', 0),
(8787, 'plPL', 'Masz coś dla mnie, $N?', 0),
(8791, 'plPL', 'Ach, $N, $gwróciłeś:wróciłaś;! I to w jednym kawałku, dodam. Jakie wieści przynosisz z Ahn\'Qiraj?', 0),
(8804, 'plPL', 'Masz coś dla mnie, $N?', 0),
(8805, 'plPL', 'Masz coś dla mnie, $N?', 0),
(8806, 'plPL', 'Masz coś dla mnie, $N?', 0),
