INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES
(2551, 'plPL', 'Layo,$B$Botrzymaliśmy hojną pomoc od tej dzielnej osoby. Wysyłam ją do ciebie do Silithusu jako wsparcie. Dopilnuj, proszę, by tak cenne wsparcie nie zostało zmarnowane w twoich wysiłkach, by odkryć tamtejsze tajemnice. Krąg z niecierpliwością czeka na wieści o postępach.$B$BNiech Cenarius czuwa nad tobą...$BRabine', 0),
(2807, 'plPL', 'Dzień 1$BNasza pielgrzymka dobiegła końca. Wreszcie dotarliśmy do Silithusu, gdzie mamy nawiązać kontakt. Przybyliśmy z wielu miejsc, by współpracować przy przedsięwzięciu, które ma być monumentalne.$B$BW powietrzu czuć ogromne podekscytowanie. Jutro poświęcimy wszystkie siły na zbudowanie tego, co pozwoli porozumieć się z NIMI.$B$BJutro zbudujemy Kamień Wiatru!', 0),
(2808, 'plPL', 'Dzień 2$BMiejsce postawienia Kamienia Wiatru było przedmiotem zażartej debaty. Nawet najmądrzejsi z nas nie potrafią z całą pewnością ustalić, które miejsce ma na myśli stare proroctwo.$B$BTrzymam się pierwotnej grupy północnej, a czas z pewnością przyzna nam rację. Argument, że linie energii przecinają się w tym miejscu pod szkodliwymi kątami, jest głupi i naiwny.$B$BJuż w wielkim tempie gromadzimy potrzebne materiały budowlane.', 0),
(2809, 'plPL', 'Dzień 15$BNasze oddanie się opłaciło. Jako pierwszy obóz ukończyliśmy budowę Kamienia Wiatru. Gdyby inni głupcy zostali z nami, zadanie zajęłoby nam niecały tydzień!$B$BJutro rozpoczniemy rytuały przywołania samego barona Kazuma. Zażądał, by to on jako pierwszy wypróbował ten system, a nie mogliśmy mu się sprzeciwić, bo łatwo wpada w gniew.$B$BSpodziewam się, że będzie z nas bardzo zadowolony.', 0);
INSERT INTO `gossip_menu_option_locale` (`MenuID`, `OptionID`, `Locale`, `OptionText`, `BoxText`) VALUES
(5703, 0, 'plPL', '<Przekaż Więzy Poszukiwacza Wiatru>.', ''),
(5779, 0, 'plPL', 'Co należy zrobić?', ''),
(5780, 0, 'plPL', 'Władca Ognia i wszyscy, którzy ośmielą się stanąć mi na drodze, zachwieją się pod moim gniewem.', ''),
(5781, 0, 'plPL', 'Przeczeszę całą ziemię w poszukiwaniu tego Kształtującego Ziemię. A co z esencją?', ''),
(5783, 0, 'plPL', 'Daj mi naczynie, najwyższy lordzie.', '');
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `MaleText`, `FemaleText`, `VerifiedBuild`) VALUES
(8619, 'plPL', 'Zawodzenie, jakie %s wydaje w chwili śmierci, poruszyło pobliski rój silithidów!', '', 0),
(8620, 'plPL', '', 'Zawodzenie, jakie %s wydaje w chwili śmierci, poruszyło pobliski rój silithidów!', 0),
(8694, 'plPL', 'Jeśli szukasz informacji, które Krąg Cenariona mógł gdzieś zarchiwizować, to $gtrafiłeś:trafiłaś; pod właściwy adres. Z drugiej strony, zanim naprawdę będę mógł pomóc, musisz najpierw wiedzieć, jakich informacji szukasz.$B$BRozumiesz, jak to działa? Genialne!', '', 0),
(8696, 'plPL', 'Przeszłość żyje na tych pustkowiach, $N. Musimy uważać, by jej nie przebudzić.', '', 0),
(9253, 'plPL', 'Spójrz na to spustoszone pole i poznaj moc, jaką władają żywioły.', '', 0),
(9296, 'plPL', 'Co o tym wiesz?', 'Co o tym wiesz?', 0),
(9297, 'plPL', 'Wiem wiele. Słuchaj i ucz się.', '', 0),
(9298, 'plPL', 'Słucham, Demitrianie.', 'Słucham, Demitrianie.', 0),
(9299, 'plPL', 'W czasach przed czasem, w epoce, którą uzurpatorzy nazwą później Pierwszą Erą Stworzenia, mój pan i jego rodzeństwo władali tym światem. To oni, Przedwieczni, stworzyli wszystko.$B$BI to oni mieli w końcu zostać strąceni przez tych, którzy nazywali siebie Kształtującymi.', '', 0),
(9301, 'plPL', 'Gdy ich widome postaci osłabły po eonach walki, uwięzieni pod światem – światem, który sami stworzyli – ulegli skażeniu tytanów Kształtujących, które przesiąkło przez powierzchnię i splugawiło Przedwiecznych.$B$BWtedy to bracia zwrócili się przeciw sobie. Przez pięć tysiącleci toczyła się bitwa w samym jądrze tego świata.', '', 0),
(9330, 'plPL', 'Bitwa?', 'Bitwa?', 0),
(9331, 'plPL', 'To podczas Rozłamu Żywiołów Władca Ognia, Ragnaros, próbował pochłonąć mojego pana, Thunderaana, Księcia Powietrza.$B$B<Demitrian pochyla głowę, a jego twarz wykrzywia wściekłość.>$B$BWypowiedz jego imię, a przyozdobię ten spustoszony obóz twoimi wnętrznościami. Milcz i słuchaj.', '', 0),
(9332, 'plPL', '<Kiwnij głową>.', '<Kiwnij głową>.', 0),
(9333, 'plPL', 'To porucznicy Ragnarosa, Geddon i Garr, dopuścili się zdrady wobec mojego pana. Thunderaan został zaskoczony.', '', 0),
(9334, 'plPL', 'Zaskoczony? Jak?', 'Zaskoczony? Jak?', 0),
(9335, 'plPL', 'Thunderaan nic nie wiedział o zamiarach Władcy Ognia. Zanim mój pan zdążył zareagować, Sulfuras, legendarny młot Ragnarosa, zadał bezlitosny cios. Thunderaan padł, całkowicie pokonany.$B$BWładca Ognia pożywił się esencją mojego pana, lecz nie zdołał pochłonąć jej w całości.', '', 0),
(9336, 'plPL', 'I co zrobił wtedy Ragnaros?', 'I co zrobił wtedy Ragnaros?', 0),
(9337, 'plPL', 'To, co zostało z esencji Thunderaana, zamknięto w talizmanie żywiołaczego spętania. Ragnaros rozbił potem talizman na dwie idealne połowy. Połowy te powierzył swoim porucznikom...', '', 0),
(9546, 'plPL', '<Demitrian pada na kolana.>$B$B$GOdzyskałeś:Odzyskałaś; wieczne więzienie mojego Pana!$B$BJakże długo czekałem na ten dzień, a teraz wreszcie nadszedł.$B$BMusi zostać uwolniony!', '', 0),
(9548, 'plPL', 'Mam naczynie jego odrodzenia. Jeśli jesteś $ggotów:gotowa; podjąć się tego zadania, będziesz $gmusiał:musiała; wzmocnić naczynie i ostatecznie złamać władzę samego Ragnarosa!', '', 0),
(9550, 'plPL', 'Naczynie odrodzenia trzeba wzmocnić elementium. Znam tylko jedno źródło tego minerału: plany żywiołów w jądrze naszego świata.$B$BJest ktoś, Kształtujący Ziemię, kto może wiedzieć więcej ode mnie o zdobywaniu takich rzeczy. Musisz odnaleźć tego Kształtującego Ziemię!', '', 0),
(9553, 'plPL', 'Cielesna postać Ragnarosa musi zostać zniszczona. Z jej szczątków wyłoni się jego esencja. W tym osłabionym stanie uścisk Ragnarosa na więzieniu Thunderaana zelżeje. Sama esencja posłuży jako klucz...', '', 0),
(9668, 'plPL', '%s rozpływa się w eterze, a wycie jego wichrów wciąż dźwięczy ci w uszach.', '', 0),
(9669, 'plPL', '%s wraz ze swoimi najeźdźczymi wojskami pojawia się wśród szalejącej pożogi na północnym zachodzie Silithusu.', '', 0),
(9679, 'plPL', '%s sprawia, że przez krainę przetacza się wichura, a odgłos jego bezrozumnej furii dobiega z północnego zachodu.', '', 0),
(9747, 'plPL', 'Przyjeżdżam do Silithusu co roku o tej porze. Pogoda robi fenomenalnie dobrze moim haluksom.$B$BPrzejdź się ze mną, przyjacielu. Popodziwiaj widoki i tak dalej.', '', 0),
(9753, 'plPL', 'Gnom? Żałosne. Staw mi czoła, demonie!', 'Gnom? Żałosne. Staw mi czoła, demonie!', 0),
(10646, 'plPL', '', 'Witaj, wędrowcze. Dopóki pozostajesz w murach Twierdzy Druidów, nic ci nie grozi.$B$BUważaj, gdy opuszczasz bezpieczne schronienie Twierdzy, bo ostatnio roi się od silithidów.', 0),
(10647, 'plPL', 'Chcę przejrzeć twoje towary, Calandrath.', 'Chcę przejrzeć twoje towary, Calandrath.', 0),
(10648, 'plPL', 'Zaopatruję Twierdzę w różne relikty potrzebne do rzucania czarów, a także w inne odczynniki alchemiczne.', '', 0),
(10649, 'plPL', 'Budzi się wielkie zło. Czujesz to?$B$BBa! Oczywiście, że nie. Daj mi swoją zbroję i broń, a przywrócę im dawną moc.', '', 0),
(10650, 'plPL', '', 'O rety, niebezpiecznie kończą mi się zapasy! Czemu ten przeklęty goblin tak się guzdrze?', 0),
(10653, 'plPL', 'Dlaczego teraz? Po prostu tego nie rozumiem. Tyle pracy do zrobienia...', '', 0),
(10654, 'plPL', 'Dowódca ostatnio nie jest sobą. Jego pani zniknęła podczas wykopalisk archeologicznych na południu pustyni – przepadła bez śladu! Doprawdy bardzo dziwne.$B$BPewnie szukasz pracy? Mam ci to wbić do głowy łopatą?', '', 0),
(10655, 'plPL', '', 'Słyszysz to, nieznajomy? Brzęczenie z każdym dniem jest coraz głośniejsze. To pewnie te kryształy doprowadzają robactwo do szału.', 0),
(10656, 'plPL', 'Spójrz w niebo, $N. Smocze stada nie pojawiały się w tej okolicy od tysiąca lat! Ci Qiraji coś knują, jestem tego pewien!', '', 0),
(10657, 'plPL', 'Miedziobrody znowu zaginął! Ten krasnolud na pewno nie odziedziczył ani krzty zdrowego rozsądku swojego brata.', '', 0),
(10672, 'plPL', 'Co... gdzie ja jestem? Tak... słabo...', '', 0),
(10675, 'plPL', 'Tak! Jestem wyleczony! Jestem wyle... ojej, za szybko wstałem!', '', 0),
(10676, 'plPL', 'Dzięki za znalezienie moich odczynników! *ziewa* Przez tę truciznę jestem... trochę zmęczony...', '', 0),
(10684, 'plPL', 'Nie służę kultowi, potworze! Chodź tu i spotkaj swoją zagładę!', 'Nie służę kultowi, potworze! Chodź tu i spotkaj swoją zagładę!', 0),
(10685, 'plPL', 'Karmazynowy templariuszu! Mam twój herb przywołania. Usłysz moje wezwanie!', 'Karmazynowy templariuszu! Mam twój herb przywołania. Usłysz moje wezwanie!', 0),
(10686, 'plPL', 'Abisalna Rada nie toleruje oszustwa! Poczuj nasz gniew, mały śmiertelniku!', '', 0),
(10690, 'plPL', 'Siwy templariuszu! Mam twój herb przywołania. Usłysz moje wezwanie!', 'Siwy templariuszu! Mam twój herb przywołania. Usłysz moje wezwanie!', 0),
(10691, 'plPL', 'Ziemny templariuszu! Mam twój herb przywołania. Usłysz moje wezwanie!', 'Ziemny templariuszu! Mam twój herb przywołania. Usłysz moje wezwanie!', 0),
(10692, 'plPL', 'Lazurowy templariuszu! Mam twój herb przywołania. Usłysz moje wezwanie!', 'Lazurowy templariuszu! Mam twój herb przywołania. Usłysz moje wezwanie!', 0),
(10694, 'plPL', 'Mój pan wpadnie w gniew, gdy dowie się o tej zasadzce. Miejmy nadzieję, że twoja śmierć go udobrucha.', '', 0),
(10695, 'plPL', 'Śmierć za Abisalną Radę to mój obowiązek i zaszczyt!', '', 0),
(10696, 'plPL', 'Twoje życie będzie stosowną ofiarą dla mojego pana, $N.', '', 0),
(10698, 'plPL', 'Wysłuchasz mnie, plugawy książę! Nie jestem pieskiem twojego Młota Zmierzchu! Jestem tu, by rzucić ci wyzwanie! Chodź! Chodź i spotkaj swoją śmierć...', 'Wysłuchasz mnie, plugawy książę! Nie jestem pieskiem twojego Młota Zmierzchu! Jestem tu, by rzucić ci wyzwanie! Chodź! Chodź i spotkaj swoją śmierć...', 0),
(10699, 'plPL', 'Książę Popiołów! Mam twój sygnet! Usłysz moje wezwanie!', 'Książę Popiołów! Mam twój sygnet! Usłysz moje wezwanie!', 0),
(10700, 'plPL', 'Książę Zefirów! Mam twój sygnet! Usłysz moje wezwanie!', 'Książę Zefirów! Mam twój sygnet! Usłysz moje wezwanie!', 0),
(10701, 'plPL', 'Książę Odłamków! Mam twój sygnet! Usłysz moje wezwanie!', 'Książę Odłamków! Mam twój sygnet! Usłysz moje wezwanie!', 0),
(10702, 'plPL', 'Książę Głębin! Mam twój sygnet! Usłysz moje wezwanie!', 'Książę Głębin! Mam twój sygnet! Usłysz moje wezwanie!', 0),
(10705, 'plPL', 'Kim jesteś? Gdzie ja jestem? Czuję się... tak słabo...', '', 0),
(10707, 'plPL', 'Nadszedł dzień sądu, potworze! Wyzywam cię na pojedynek!', 'Nadszedł dzień sądu, potworze! Wyzywam cię na pojedynek!', 0),
(10708, 'plPL', 'Skaldrenoksie! Mam twoje berło i nakazuję ci wkroczyć do tego świata!', 'Skaldrenoksie! Mam twoje berło i nakazuję ci wkroczyć do tego świata!', 0),
(10709, 'plPL', 'Whirlaksisie! Mam twoje berło! Rozkazuję ci wkroczyć do tego świata!', 'Whirlaksisie! Mam twoje berło! Rozkazuję ci wkroczyć do tego świata!', 0),
(10710, 'plPL', 'Kazumie! Mam twoje berło! Rozkazuję ci wkroczyć do tego świata!', 'Kazumie! Mam twoje berło! Rozkazuję ci wkroczyć do tego świata!', 0),
(10711, 'plPL', 'Skwolu! Mam twoje berło! Rozkazuję ci wkroczyć do tego świata!', 'Skwolu! Mam twoje berło! Rozkazuję ci wkroczyć do tego świata!', 0),
(10713, 'plPL', 'No to lepiej usiądź, to będzie długa historia.$B$BGdy przybyliśmy do Silithusu, pani Mar\'alith jako pierwsza z nocnych elfów z Twierdzy Druidów dołączyła do wyprawy. Nasza praca nie odbiegała od normy: zebrać grupę, wyprawić się do różnych rojów i szukać zaginionych artefaktów.', '', 0),
(10714, 'plPL', 'To brzmi niebezpiecznie.', 'To brzmi niebezpiecznie.', 0),
(10715, 'plPL', 'Pewnie, że tak! W tych rojach aż huczało od różnych silithidów, które wcale nie cieszyły się na nasz widok.$B$BWszystko szło dobrze, dopóki nie natknęliśmy się na kryształ z glifami w Roju Regal. Ciągnęło ją do niego jak ćmę do ognia! Przyłożyła swój śliczny policzek do kryształu i od razu wpadła w coś w rodzaju transu. Rzecz jasna, moja ekipa się zaniepokoiła. Podnieśliśmy ją i wynieśliśmy stamtąd w te pędy!', '', 0),
(10716, 'plPL', 'Co się z nią potem stało?', 'Co się z nią potem stało?', 0),
(10717, 'plPL', 'Zanieśliśmy ją do dowódcy w nadziei, że druidzi z Kręgu postawią ją na nogi. No i faktycznie zdołali ją obudzić. Uznaliśmy, że nasze sprawy z Kręgiem są załatwione i możemy wrócić do pracy.$B$BMinęło kilka tygodni i wszystko szło dobrze. Brann był wtedy jeszcze z nami, więc w pracy panował jaki taki porządek. Aż pewnego dnia, ni stąd, ni zowąd, znów zjawiła się w naszym obozie.', '', 0),
(10718, 'plPL', 'Natalia?', 'Natalia?', 0),
(10719, 'plPL', '$GZgłupiałeś:Zgłupiałaś;? O kim innym miałbym mówić? Tak, o tej dziewczynie – pani Mar\'alith. W każdym razie wróciła, i to nie w najlepszym humorze. Wtedy posypały się żądania.', '', 0),
(10720, 'plPL', 'Jakie żądania?', 'Jakie żądania?', 0),
(10721, 'plPL', 'Zażądała, żebyśmy natychmiast wrócili do Roju Regal! Brann nie zamierzał tolerować takich fochów. Powiedział jej, że nie ma mowy, żebyśmy wrócili do tych rojów bez wsparcia armii. Zrobiło się tam o wiele za niebezpiecznie. Tych śmierdzących insektów było chyba trzy razy więcej niż za pierwszym razem.$B$BWtedy Natalii odbiło!', '', 0),
(10722, 'plPL', 'Odbiło? Co masz na myśli?', 'Odbiło? Co masz na myśli?', 0),
(10723, 'plPL', 'Jak to, co mam na myśli? Zwariowała! Dziewczyna kompletnie oszalała. Normalnie nie biję dziewczyn, ale kiedy odzyskałem przytomność, byłem cholernie wściekły. Brann, Rutgar, ja i małpka rzuciliśmy się na nią jak orki! Cud, że zdołaliśmy ją odeprzeć. Wyglądała, jakby była opętana!', '', 0),
(10724, 'plPL', 'Opętana przez co?', 'Opętana przez co?', 0),
(10725, 'plPL', 'Kto to wie? W każdym razie wtedy widziałem ją po raz ostatni. Może Frankal da ci lepsze informacje.$B$BNie chcę zbaczać z tematu, bo na pewno twoja praca dla dowódcy jest ważna, ale jesteśmy tu na tropie czegoś wielkiego. WIELKIEGO! Nasze prośby do Żelaznej Kuźni o armię jak dotąd trafiają w próżnię. Podobno jesteśmy zbyt rozproszeni, broniąc królestwa, czy jakieś inne bzdury. Jak już zdasz raport dowódcy, wróć tu z przyjaciółmi. Potrzebujemy twojej pomocy!', '', 0),
(10726, 'plPL', 'Wrócę, gdy uporządkuję ten bałagan.', 'Wrócę, gdy uporządkuję ten bałagan.', 0),
(10727, 'plPL', 'Witaj, Frankalu. Podobno możesz wiedzieć, gdzie przebywa pani Natalia Mar\'alith.', 'Witaj, Frankalu. Podobno możesz wiedzieć, gdzie przebywa pani Natalia Mar\'alith.', 0),
(10728, 'plPL', 'O rany, znowu to samo... Siadaj, $gsynku:panienko;.$B$BRutgar na pewno opowiedział ci już część tej historii, więc oszczędzę ci nudnych szczegółów i przejdę od razu do sedna.', '', 0),
(10729, 'plPL', 'To lubię słyszeć.', 'To lubię słyszeć.', 0),
(10730, 'plPL', 'No dobra! Więc pani wróciła, żeby drugi raz spróbować szczęścia w rojach, ale Brann nie chciał słyszeć o tych bzdurach! Zanim zaczęła się bijatyka, zaczęła rozmawiać z czymś albo z kimś. Co gorsza, zaczęła zawodzić w języku, którego nikt z nas nigdy nie słyszał.', '', 0),
(10731, 'plPL', 'To dziwne.', 'To dziwne.', 0),
(10732, 'plPL', 'Mnie to mówisz! Tym dziwniejsze, że Brann, Rutgar, ja i małpka znamy razem 38 różnych języków, w tym trochę tytańskiego – zarówno vanir, jak i aesir.$B$BW każdym razie o czymkolwiek tam klekotała, na pewno nie rozmawiała z nikim „obecnym”. Potem kiwnęła głową i przeszła do ataku! Po prostu się na nas rzuciła!', '', 0),
(10733, 'plPL', 'Nie daliście rady samotnej kapłance nocnych elfów?', 'Nie daliście rady samotnej kapłance nocnych elfów?', 0),
(10734, 'plPL', 'Słuchaj, $gsynku:panienko;, wiedz, że to, co nas zaatakowało, nie było żadną kapłanką! Oczy jej płonęły czymś złym i dosłownie toczyła pianę z ust! Wpadła, wydała jakiś szalony wrzask, od którego wszyscy rozbiegliśmy się na różne strony, a potem zaczęła nam po kolei rozdzierać umysły. Słyszałem w głowie mroczne słowa i widziałem, jak inni co chwila tracą przytomność. To było szaleństwo! Byłoby po nas, gdyby nie ta przeklęta małpa.', '', 0),
(10735, 'plPL', 'Właśnie, co z tą małpą?', 'Właśnie, co z tą małpą?', 0),
(10736, 'plPL', 'A o co tu pytać? To małpa, ty wariacie. No więc tak, małpa wpadła w szał, jak zobaczyła, że stary Brann pada twarzą w piach. Cokolwiek ta nocna elfka robiła, nie powstrzymało Glibba przed okładaniem jej po łepetynie.', '', 0),
(10737, 'plPL', 'I co potem?', 'I co potem?', 0),
(10738, 'plPL', 'Powiem ci, co potem. Pobiegła prosto do roju. I wiesz, co jest jeszcze bardziej szalone? Ani jeden przeklęty robal nie stanął jej na drodze ani nie próbował jej zatrzymać. Przebiegła przez nie wszystkie, jakby była z nimi za pan brat od stuleci.', '', 0),
(10739, 'plPL', 'Co za historia! Więc weszła do Roju Regal i wtedy widzieliście ją po raz ostatni?', 'Co za historia! Więc weszła do Roju Regal i wtedy widzieliście ją po raz ostatni?', 0),
(10740, 'plPL', 'Tak.', '', 0),
(10741, 'plPL', 'Dzięki za informacje, Frankalu.', 'Dzięki za informacje, Frankalu.', 0),
(10742, 'plPL', '', 'Będziesz stosowną ofiarą!', 0),
(10743, 'plPL', '', 'C\'Thun odzyska ten świat!', 0),
(10744, 'plPL', 'Kryształ pokrywają misterne glify i runy. Nie potrafisz nic z nich zrozumieć.', '', 0),
(10745, 'plPL', 'Z wnętrza kamienia dobiega cichy szept...$B$BWitaj, maleńki. Masz wieści dla templariusza?', 'Z wnętrza kamienia może dobiec szept...$B$BWitaj, maleńki. Masz wieści dla templariusza?', 0),
(10746, 'plPL', 'Z wnętrza kamienia dobiega wyraźny głos...$B$BGdzie twój medalion rangi, maleńki? Nie możesz rozmawiać z księciem bez dowodu tytułu...', 'Gdzie twój medalion rangi, maleńki? Nie możesz rozmawiać z księciem bez dowodu tytułu...', 0),
(10750, 'plPL', 'Z kamienia rozlega się grzmiący głos...$B$BCo to? Wyczuwam małego kultystę, który się tu kręci! Zmykaj, robaku, albo poczujesz gniew lordów Rady!', 'Z kamienia rozlega się grzmiący głos...$B$BCo to? Wyczuwam małego kultystę, który się tu kręci! Zmykaj, robaku, albo poczujesz gniew lordów Rady!', 0),
(10751, 'plPL', '', 'Zawsze byłeś w rodzinie tym, który sprawia kłopoty, Noggle. Zawsze!', 0),
(10752, 'plPL', '<Użyj urządzenia transkrypcyjnego, by sporządzić odbitkę.>', '<Użyj urządzenia transkrypcyjnego, by sporządzić odbitkę.>', 0),
(10754, 'plPL', 'Duchy Silithusu wołają do nas, $N. Ziemia płacze, bo ma do opowiedzenia żałosną historię...', '', 0),
(10759, 'plPL', '', 'Krąg Cenariona jest mądry i zgłębił wiele tajemnic ziemi. Rzemieślnicy dobrze zrobią, słuchając słów tych druidów.', 0),
(10760, 'plPL', '', 'Upiorna postać patrzy na ciebie nieufnie i milczy.', 0),
(10762, 'plPL', '', 'Postaram się przetłumaczyć i opisać to, co widzę.', 0),
(10781, 'plPL', 'Mamy w Silithusie więcej niż jednego wroga, $N.$B$BPodczas gdy uwaga wszystkich skupia się na silithidach, ja i mój starszy brat bacznie obserwujemy tych szaleńców z Młota Zmierzchu.', '', 0),
(10790, 'plPL', '', 'Witaj, wędrowcze. To tutaj, blisko 1000 lat temu, Qiraji rozpoczęli swój niszczycielski marsz przez Kalimdor.$B$BPodczas wojny zginęły tysiące istnień, większość na tej przeklętej pustyni podczas pierwszej inwazji.$B$BJestem jedną z nielicznych, które pozostały, przykuta zarówno do przeszłości, jak i do teraźniejszości. Nie wiem, dlaczego mam tu pozostać na posterunku, ale wiem, że muszę.', 0),
(10791, 'plPL', 'Skąd wiesz?', 'Skąd wiesz?', 0),
(10792, 'plPL', '', 'Zginęłam już sto razy. Zawsze budzę się tutaj, żywa. Niektórzy mówią, że jestem przeklęta, a inni...', 0),
(10793, 'plPL', 'Co mówią?', 'Co mówią?', 0),
(10794, 'plPL', '', 'Mówią, że jestem błogosławiona: że jestem heroldką, która zwiastuje nową epokę.', 0),
(10795, 'plPL', 'A co ty mówisz?', 'A co ty mówisz?', 0),
(10796, 'plPL', '', 'Budzą się pradawne siły – siły, których nie widziano ani nie czuto od tysięcy lat. Świat płacze. Być może nadchodzi nowy rozłam. Choroba zrodzona od środka...$B$BPlugastwo zaczęło przesiąkać do naszych ziem. Ze Snu rodzą się koszmary. Koszmary, które plugawią nas na jawie...', 0),
(10801, 'plPL', 'Zapłacisz najwyższą cenę za tę zuchwałość, mały robaku. Twoja dusza należy do mnie!', '', 0),
(10802, 'plPL', 'Ten akt nieposłuszeństwa nie ujdzie bezkarnie. Ty i twój świat zginiecie!', '', 0),
(10803, 'plPL', 'Co? Takie małe, wątłe stworzenie mnie wzywa? To nie ujdzie bezkarnie!', '', 0),
(10804, 'plPL', 'Oszust! Zostać przywołanym przez takie szczenię jak ty to hańba bez równych! GIŃ!', '', 0),
(10829, 'plPL', '', 'To historia... Historia Silithusu... Ahn\'Qiraj... tytanów i Przedwiecznych... Czytam z proroctwa C\'Thuna spisanego przez qirajskiego proroka Skerama. Proroctwa, które zapowiada kataklizm...', 0),
(10830, 'plPL', '', 'W czasach przed czasem, gdy świat był jeszcze w powijakach, na tej właśnie ziemi szalała bitwa między tytanem a istotą o niewyobrażalnym złu i potędze. Proroctwo nie mówi jasno, czy tytan został w tej bitwie pokonany, ale przedstawia, że tytan poległ. Poległ też Przedwieczny – a przynajmniej tak sądzono.', 0),
(10831, 'plPL', '', 'Przez tysiąclecia ta istota spoczywała uśpiona pod światem, czekając na swój czas. Ze swojego więzienia wypatrywała dokładnie tej chwili, w której mogłaby uderzyć na tych, którzy chcieli jej zguby.', 0),
(10832, 'plPL', '', 'Kraina wiecznego blasku gwiazd, Kalimdor, była troskliwą matką dla wszystkich swoich stworzeń. Magia Studni Wieczności przenikała ziemię i wzmacniała mnogość roślin i zwierząt, które uczyniły ten świat swoim domem. Z tego magicznego eteru narodziły się silithidy. To przez silithidy posępny Przedwieczny sięgał po świat, który niegdyś trzymał w bezlitosnym uścisku, i próbował go rozerwać.', 0),
(10833, 'plPL', '', 'Przedwieczny stworzył z silithidów awatary na swój obraz. Awatary te miały zostać nazwane Qiraji. Świadomi i obdarzeni celem, Qiraji nadali imię swemu stwórcy: tak narodził się C\'Thun... Przez wiele tysięcy lat Qiraji gorączkowo budowali siłę zdolną obrócić w perzynę świat, który zdradził ich boga. Wielka forteca-miasto Ahn\'Qiraj powstała, by pomieścić ich rosnące armie i przygotować się na nadejście C\'Thuna.', 0),
(10836, 'plPL', '', 'To nie może być prawda. Nie można pozwolić, by Przedwieczny wkroczył do tego świata. Skutki byłyby... O rety!', 0),
(10837, 'plPL', '', '%s odzyskuje panowanie nad sobą.', 0),
(10838, 'plPL', '', 'Jest tego więcej.', 0),
(10839, 'plPL', '', 'Chwila, na którą C\'Thun tak cierpliwie czekał, wreszcie nadeszła. Jego dzieci przez tysiące lat budowały armię zdolną zemścić się na całym Kalimdorze, a teraz nagroda była w ich zasięgu.', 0),
(10840, 'plPL', '', 'Tytani dawno już opuścili ten świat. Bronić go mogły tylko nocne elfy, które niegdyś zamieszkiwały te tereny. O rety! Następny ustęp jest fascynujący!', 0),
(10841, 'plPL', '', 'Pierwszą inwazją na Silithus dowodził potężny Qiraji zwany generałem Rajaxxem. Na jego drodze stanął tylko jeden: nocny elf zwany Jeleniorogim. Nazywają go Khar\'sis, czyli w rodzimym języku Qiraji „ręka ziemi”.', 0),
(10842, 'plPL', '', 'Jeleniorogi i jego armie byli wyraźnie przytłoczeni, gdy do Silithusu wlewały się niekończące się zastępy Rajaxxa. Wydaje się jednak, że Jeleniorogi był dla Qiraji czymś więcej niż tylko utrapieniem. Pod jego wodzą wszystkie armie nocnych elfów zjednoczyły się w obronie Kalimdoru, znacznie spowalniając siły Qiraji.', 0),
(10843, 'plPL', '', 'Niestety obrona nocnych elfów była nie do utrzymania, a Rajaxx wiedział, że długo już nie wytrzymają. Ich zawziętość doprowadzała jednak Rajaxxa do wielkiej frustracji, a jego króla do jeszcze większej. Chwileczkę, królów? Niesamowite...', 0),
(10844, 'plPL', '', 'Vek\'nilash i Vek\'lor, zwani Bliźniaczymi Cesarzami Ahn\'Qiraj, obserwowali wojnę z sanktuarium swojej świątyni. Przebiegli bracia obmyślili plan, by zdemoralizować i podzielić siły Jeleniorogiego.', 0),
(10845, 'plPL', '', 'Valstann Jeleniorogi był prawą ręką Fandrala. Dumny i szlachetny wojownik, niezachwiany w oddaniu i uwielbieniu dla ojca... a Bliźniaczy Cesarze wyczuli w tym słabość. Słabość, którą można było wykorzystać.', 0),
(10846, 'plPL', '', 'Siłom Qiraji rozkazano się wycofać i ukryć większość swoich zastępów pod piaskami pustyni. Podczas gdy pierwsze linie armii Jeleniorogiego były zajęte, zarządzono niewielki atak na Osadę Południowego Wiatru.', 0),
(10847, 'plPL', '', 'Valstann, pragnąc zadowolić ojca, przekonał Fandrala, by pozwolił mu poprowadzić mały batalion na obronę Południowego Wiatru. Skoro losy bitwy zaczynały się odwracać na ich korzyść, jego ukochanemu dziecku z pewnością nic nie groziło. Nie dostrzeżono pułapki. Valstann został pojmany przez ukrytych Qiraji, a Osada Południowego Wiatru zrównana z ziemią. Sam Rajaxx zabrał pojmanego Valstanna na pierwszą linię bitwy, gdzie – na oczach Jeleniorogiego i sił nocnych elfów – brutalnie stracił młodego nocnego elfa.', 0),
(10848, 'plPL', '', 'Wojna trwała dalej, ale wola wielkiego przywódcy została złamana. Wkrótce cały Silithus pochłonęły silithidy i ich qirajscy panowie.', 0),
(10849, 'plPL', '', 'Biedak, to tak wiele wyjaśnia.', 0),
(10850, 'plPL', '', 'Armię nocnych elfów zepchnięto przez Un\'Goro aż do granic pustyni Tanaris. Coś w Un\'Goro nie pozwoliło Qiraji zająć tej krainy. Nie do końca rozumiem to słowo, ale sądzę, że oznacza „Ziemie Bogów”. Napisano, że nie mogli „zająć Ziem Bogów”.', 0),
(10851, 'plPL', 'Fascynujące, to zgadza się z teoriami, według których Un\'Goro było domem tytanów, gdy zamieszkiwali Kalimdor. Może sam Aman\'Thul czuwał nad „Ziemiami Bogów”.', 'Fascynujące, to zgadza się z teoriami, według których Un\'Goro było domem tytanów, gdy zamieszkiwali Kalimdor. Może sam Aman\'Thul czuwał nad „Ziemiami Bogów”.', 0),
(10852, 'plPL', '', 'Hmm, ciekawe... To urywa się nagle. W Tanaris Qiraji zapisali starcie z brązowym smokiem. Wiele tu brakuje... Trzeba znaleźć więcej informacji! Na pewno planują ponownie najechać Kalimdor!', 0),
(10857, 'plPL', 'Odejdź natychmiast, nieznajomy! Nie mam z tobą nic do załatwienia.', '', 0),
(10946, 'plPL', 'Cały czas dostaję raporty o twoich wyczynach przeciw Abisalnej Radzie, $N. Dokonujesz tam wielkich rzeczy!$B$BTak trzymaj, a nie pożałujesz!', '', 0),
(11005, 'plPL', '', 'Witaj, $N. Brygada Żelaznej Kuźni stacjonuje tutaj, by mieć oko na Rój Zora. Druidzi z Kręgu Cenariona obserwują ruchy silithidów i spodziewają się w tej okolicy czegoś poważnego.', 0),
(11273, 'plPL', 'Służymy Thrallowi z wielką dumą. Pójdziemy tak daleko, jak będzie trzeba, by pokonać wroga.', '', 0),
(11318, 'plPL', 'Trzeba trochę wprawy, żeby być tak blisko silithidów i nie zwrócić na siebie uwagi. Jeśli możesz, lepiej tego nie próbuj.', '', 0),
(11321, 'plPL', 'Nie zrozum mnie źle, wolałbym nie siedzieć dzień w dzień w tunelu pełnym silithidów, ale jeśli ukrywanie się tutaj i obserwowanie ruchów tych stworzeń ma nam pomóc wygrać wojnę, to zostanę, ile będzie trzeba.', '', 0),
(11322, 'plPL', 'Wkrótce uwolnimy Azeroth od odrażającej obecności silithidów. Ich niszczycielski potencjał jest znacznie większy niż to, co $gwidziałeś:widziałaś; na własne oczy, $N. Za ich działaniami stoją większe, mroczniejsze moce.', '', 0),
(11325, 'plPL', 'Przychodzę po twój raport.', 'Przychodzę po twój raport.', 0),
(11385, 'plPL', 'Witaj, $N. Jestem Leoren, zarządca stajni w Twierdzy Druidów.', '', 0),
(11393, 'plPL', 'Teraz, gdy wojna rozgorzała na dobre, nie brakuje nam zdolnych do walki wojowników z Hordy i Przymierza.$B$BGdybyśmy tylko mogli powstrzymać ich przed skakaniem sobie do gardeł...', '', 0),
(11658, 'plPL', '„Świetna robota przy zbieraniu zasobów na wojnę” – mówili. „Masz awans” – mówili. A tak naprawdę chodziło im o to, że „Stacjonujesz pod robaczym rojem w Silithusie z bandą spoconych krasnoludów, Carnes!”.$B$BDzięki za awans, kapitanie!', '', 0),
(11661, 'plPL', 'Jak wielu innych przybyłem, by wesprzeć moich braci druidów, gdy wybuchła wojna.$B$BTeraz, gdy Wrota Ahn\'Qiraj są otwarte, zrozumiałem, że wciąż zostało wiele do zrobienia. Postanowiłem zostać w Silithusie i jak najlepiej wspierać naszą sprawę, $N.', '', 0),
(11662, 'plPL', 'Choć silithidy wydają się zabójcze, to tylko potulne stworzenia w porównaniu z ich qirajskimi panami.', '', 0),
(11663, 'plPL', 'Ta wojna się nie skończyła, dopiero się zaczęła! Nasi dzielni mężczyźni i kobiety walczą z wrogiem w Ahn\'Qiraj dniem i nocą, $N. Niedługo miasto Qiraji upadnie.', '', 0),
(11664, 'plPL', '', 'Nasze stałe postępy w walce z Qiraji zawdzięczamy różnorodnej pomocy, jaką otrzymaliśmy niemal z każdego zakątka Kalimdoru.$B$BDo prowadzenia wojny potrzeba czegoś więcej niż żołnierzy, $N. Wielu nieopiewanych bohaterów tej wojny to kupcy i rzemieślnicy, którzy zaopatrują nasze siły we wszystko, czego potrzebują.', 0),
(11788, 'plPL', 'Pozdrowienia i wyrazy szacunku z Dworu Krukowiska, $gpodróżniku:podróżniczko;.', '', 0),
(18943, 'plPL', 'Mów dalej, proszę.', 'Mów dalej, proszę.', 0);
